window.TADABBUR_MUHAMMAD = {"_meta":{"description":"تدبّر سورة محمد ﷺ (٤٧)، وسورةٌ مدنيّةٌ، تُسمّى أيضًا سورةَ القتالِ لذكرِ أحكامه. محورُها المقابلةُ بين الذين كفروا وصدّوا عن سبيلِ الله فأضلّ أعمالهم، والذين آمنوا وعملوا الصالحاتِ فكفّر عنهم سيّئاتهم؛ وأحكامُ الجهادِ وأسرى الحرب، ووعدُ نصرِ الله لمن نصره، وذمُّ المنافقين الذين كرهوا القتالَ ولم يتدبّروا القرآن، والحثُّ على طاعةِ الله والرسولِ والإنفاقِ في سبيله. فيها «إن تنصروا الله ينصركم ويثبت أقدامكم»، و«أفلا يتدبرون القرآن أم على قلوب أقفالها»، و«فاعلم أنه لا إله إلا الله»، و«إنما الحياة الدنيا لعب ولهو».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":47,"name":"محمد","total_ayahs":38,"audio":[1,7,15,19,21,24,31,33,36,38],"passages":[{"title":"المقابلةُ بين الكفّارِ والمؤمنين وأعمالهم","range":[1,3],"theme":"إضلالُ الله أعمالَ الذين كفروا وصدّوا عن سبيله، وتكفيرُه سيّئاتِ الذين آمنوا وعملوا الصالحاتِ وآمنوا بما نُزِّل على محمد، وأنّ سببَ ذلك اتّباعُ الكفّارِ الباطلَ واتّباعُ المؤمنين الحقَّ من ربّهم","verses":[{"n":1,"reflection":{"text":"«الذين كفروا وصدوا عن سبيل الله أضل أعمالهم»: الذين كفروا وصدّوا الناسَ عن دينِ الله أبطل الله أعمالهم فلا ثوابَ لها؛ ففي هذا بيانُ حبوطِ أعمالِ الكافرين الصادّين؛ فاحذر الكفرَ والصدَّ عن سبيلِ الله فيحبط عملك، فاعمل مؤمنًا محتسبًا، فالكفرُ والصدُّ يبطلان العمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ والاحتسابُ في العمل، والحذرُ من الصدِّ عن سبيلِ الله."},"action":{"text":"تأمّل بيانَ حبوطِ أعمالِ الكافرين: الذين كفروا بالله ورسوله، وصدّوا غيرهم عن سبيلِ الله ودينه، أضلَّ الله أعمالهم وأبطلها، فلا ينتفعون بها، ولا يجدون لها ثوابًا في الآخرة؛ بل تذهب هباءً «الذين كفروا وصدوا عن سبيل الله أضل أعمالهم»؛ ففي هذا بيانُ أنّ الكافرين الصادّين عن سبيلِ الله تحبط أعمالهم فلا تنفعهم؛ فما عملوه من خيرٍ في الظاهرِ لا وزنَ له لفسادِ أصله؛ وقدمنا إلى ما عملوا من عملٍ فجعلناه هباءً منثورًا؛ فاحذر الكفرَ والصدَّ عن سبيلِ الله، فإنهما يبطلان العمل؛ واعمل عملك مؤمنًا بالله محتسبًا وجهه؛ فالعملُ لا ينفع إلا بالإيمانِ والإخلاص؛ فمن عمل صالحًا من ذكرٍ أو أنثى وهو مؤمن؛ فمن كفر وصدَّ حبط عمله، ومن آمن وأخلص قُبِل عمله؛ فاجعل إيمانك وإخلاصك أساسَ كلِّ عمل؛ فبالإيمانِ والاحتسابِ ينفعك عملك وينجو من الحبوط."}},{"n":2,"reflection":{"text":"«والذين آمنوا وعملوا الصالحات وآمنوا بما نزل على محمد وهو الحق من ربهم كفر عنهم سيئاتهم وأصلح بالهم»، والذين آمنوا وعملوا الصالحاتِ وآمنوا بالقرآنِ المنزَّلِ على محمدٍ وهو الحقّ، كفّر الله عنهم سيّئاتهم وأصلح شأنهم؛ ففي هذا بيانُ جزاءِ المؤمنين العاملين؛ فآمن واعمل صالحًا وآمن بما نزل على محمد، فثمرةُ ذلك تكفيرُ السيّئاتِ وصلاحُ الحال، فاجمع بين الإيمانِ والعملِ واتّباعِ الوحي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الإيمانِ والعملِ الصالحِ واتّباعِ الوحي، لتكفيرِ السيّئات."},"action":{"text":"تأمّل جزاءَ المؤمنين العاملين: والذين آمنوا بالله ورسوله، وعملوا الأعمالَ الصالحاتِ من الطاعات، وآمنوا بما نُزِّل على محمدٍ ﷺ، وهو القرآنُ الحقُّ من ربّهم، كفّر الله عنهم سيّئاتهم فلم يؤاخذهم بها، وأصلح بالهم وشأنهم وحالهم في الدنيا والآخرة «والذين آمنوا وعملوا الصالحات وآمنوا بما نزل على محمد وهو الحق من ربهم كفر عنهم سيئاتهم وأصلح بالهم»؛ ففي هذا بيانُ جزاءِ من جمع بين الإيمانِ والعملِ الصالحِ والإيمانِ بالقرآن: تكفيرُ السيّئاتِ وإصلاحُ الحال؛ فخصَّ الإيمانَ بما نُزِّل على محمدٍ بالذكرِ لأهميّته؛ فآمن أنت بالله ورسوله، واعمل الصالحات، وآمن بالقرآنِ الحقِّ واتّبعه؛ فثمرةُ ذلك تكفيرُ سيّئاتك وإصلاحُ شأنك؛ إنّ الحسناتِ يذهبن السيّئات؛ ومن يؤمن بالله ويعمل صالحًا يكفّر عنه سيّئاته ويدخله جنّات؛ فاجمع بين الإيمانِ والعملِ الصالحِ واتّباعِ الوحي؛ فمن جمعها كُفّرت سيّئاته وأُصلِح حاله، ومن فرّط خسر؛ فاجعل إيمانك وعملك واتّباعك للقرآنِ سبيلَ تكفيرِ سيّئاتك."}},{"n":3,"reflection":{"text":"«ذلك بأن الذين كفروا اتبعوا الباطل وأن الذين آمنوا اتبعوا الحق من ربهم كذلك يضرب الله للناس أمثالهم»: ذلك الجزاءُ لأنّ الكافرين اتّبعوا الباطلَ والمؤمنين اتّبعوا الحقَّ من ربّهم، كذلك يضرب الله للناسِ أمثالهم؛ ففي هذا بيانُ سببِ اختلافِ الجزاء؛ فاتّبع الحقَّ من ربّك ودع الباطل، فمن اتّبع الحقَّ فاز ومن اتّبع الباطلَ خسر، فاجعل الحقَّ متّبعك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الحقِّ من الله وتركُ الباطل، وإدراكُ سببِ اختلافِ الجزاء."},"action":{"text":"تأمّل بيانَ سببِ اختلافِ الجزاء: ذلك التفاوتُ في الجزاء، حبوطُ أعمالِ الكافرين، وتكفيرُ سيّئاتِ المؤمنين، سببه أنّ الذين كفروا اتّبعوا الباطلَ في اعتقادهم وأعمالهم، وأنّ الذين آمنوا اتّبعوا الحقَّ الثابتَ من ربّهم؛ كذلك يضرب الله للناسِ أمثالهم ويبيّن لهم أحوالهم ليعتبروا «ذلك بأن الذين كفروا اتبعوا الباطل وأن الذين آمنوا اتبعوا الحق من ربهم كذلك يضرب الله للناس أمثالهم»؛ ففي هذا بيانُ أنّ سببَ اختلافِ الجزاءِ اختلافُ المتَّبَع: الباطلُ أو الحق؛ فالكافرُ اتّبع الباطل فحبط عمله، والمؤمنُ اتّبع الحقَّ ففاز؛ فاتّبع أنت الحقَّ الثابتَ من ربّك في العقيدةِ والعبادةِ والمعاملة؛ ودع الباطلَ في كلِّ صوره؛ فالحقُّ من ربّك، والباطلُ من الشيطانِ والهوى؛ فمن اتّبع الحقَّ فاز ونجا، ومن اتّبع الباطلَ خسر وهلك؛ ذلك بأنّ الله هو الحقُّ وأنّ ما يدعون من دونه الباطل؛ فاجعل الحقَّ من ربّك هو متّبعك في كلِّ أمر؛ فباتّباعِ الحقِّ تفوز، وباتّباعِ الباطلِ تخسر."}}]},{"title":"أحكامُ الجهادِ والأسرى، وجزاءُ الشهداء","range":[4,6],"theme":"حكمُ لقاءِ الكفّارِ بضربِ الرقابِ والأسرِ والمنِّ أو الفداء، وأنّ الله لو شاء لانتصر لكن ليبتليَ بعضكم ببعض، وأنّ الذين قُتِلوا في سبيلِ الله لن يُضِلَّ أعمالهم بل يهديهم ويصلح بالهم ويدخلهم الجنّةَ التي عرّفها لهم","verses":[{"n":4,"reflection":{"text":"«فإذا لقيتم الذين كفروا فضرب الرقاب حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما فداء حتى تضع الحرب أوزارها... والذين قتلوا في سبيل الله فلن يضل أعمالهم»: فإذا لقيتم الكفّارَ في القتالِ فاضربوا الرقاب حتى تُثخنوهم، فأسِروهم، ثم إمّا منٌّ وإمّا فداء، حتى تنتهيَ الحرب؛ ولو شاء الله لانتقم منهم لكن ليبلوَ بعضكم ببعض؛ والذين قُتِلوا في سبيلِ الله لن يُضِلَّ أعمالهم؛ ففي هذا أحكامُ الجهادِ وأسراه، وحكمةُ الابتلاءِ بالقتال، وثوابُ الشهداء؛ فجاهد في سبيلِ الله ممتثلًا شرعه، واعلم أنّ الابتلاءَ بالقتالِ حكمةٌ إلهية، وأنّ الشهيدَ لا يضيع عمله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"امتثالُ شرعِ الله في الجهاد، وإدراكُ حكمةِ الابتلاء، ورجاءُ ثوابِ الشهادة."},"action":{"text":"تأمّل أحكامَ الجهادِ وحكمتَه: فإذا لقيتم، أيها المؤمنون، الذين كفروا في ساحةِ القتال، فاضربوا رقابهم بالسيف؛ حتى إذا أكثرتم فيهم القتلَ وأضعفتموهم، فأسِروهم وشدّوا وثاقهم؛ ثم أنتم بالخيار في الأسرى: إمّا المنُّ عليهم بإطلاقهم بلا مقابل، وإمّا فداؤهم بمالٍ أو أسرى؛ استمرّوا على ذلك حتى تنتهيَ الحربُ وتضع أوزارها؛ ذلك حكمُ الله؛ ولو شاء الله لانتصر من الكفّارِ بلا قتال، ولكن ليبلوَ بعضكم ببعضٍ ويمتحن المؤمنَ بالكافر؛ والذين قُتِلوا في سبيلِ الله شهداءَ فلن يُضِلَّ الله أعمالهم بل يتقبّلها ويثيبهم «فإذا لقيتم الذين كفروا فضرب الرقاب... والذين قتلوا في سبيل الله فلن يضل أعمالهم»؛ ففي هذا بيانُ أحكامِ القتالِ والأسرى، وأنّ الابتلاءَ بالقتالِ حكمةٌ إلهية، وأنّ الشهيدَ لا يضيع عمله؛ فجاهد في سبيلِ الله بالنيّةِ والامتثالِ لشرعه؛ واعلم أنّ الله لو شاء لكفى المؤمنين القتال، لكنه ابتلاهم به لحكمة؛ ولا تحسبنّ الذين قُتِلوا في سبيلِ الله أمواتًا بل أحياءٌ عند ربّهم يُرزَقون؛ فارجُ ثوابَ الشهادةِ والجهادِ في سبيلِ الله؛ فمن جاهد ممتثلًا شرعَ الله فاز، والشهيدُ لا يضيع عمله؛ فاجعل جهادك موافقًا لشرعِ الله راجيًا ثوابه."}},{"n":5,"reflection":{"text":"«سيهديهم ويصلح بالهم»: سيهدي الله الشهداءَ ويصلح شأنهم؛ ففي هذا بيانُ جزاءِ الشهداءِ بالهدايةِ وصلاحِ الحال؛ فاعمل عملَ الشهداءِ المخلصين لتنال الهدايةَ وصلاحَ الحال، فمن جاهد في سبيلِ الله هداه وأصلح حاله، فأخلص جهادك لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ في العملِ لنيلِ الهدايةِ وصلاحِ الحال."},"action":{"text":"تأمّل جزاءَ الشهداء: سيهدي الله الذين قُتِلوا في سبيله إلى منازلهم في الجنّة، أو يهديهم في الآخرةِ إلى موجباتِ رضاه، ويصلح بالهم وشأنهم وأحوالهم فلا يشقون «سيهديهم ويصلح بالهم»؛ ففي هذا بيانُ أنّ الله يهدي الشهداءَ ويصلح شأنهم جزاءَ جهادهم وإخلاصهم؛ فبعد أن أخبر أنه لن يُضِلَّ أعمالهم، بشّرهم بالهدايةِ وصلاحِ الحال؛ فيهديهم ويصلح أمورهم في الآخرة؛ والذين جاهدوا فينا لنهدينّهم سبلنا؛ ومن يؤمن بالله يهدِ قلبه؛ فاعمل أنت عملَ الشهداءِ المخلصين المجاهدين في سبيلِ الله؛ لتنال الهدايةَ وصلاحَ الحال؛ فمن جاهد في سبيلِ الله بإخلاصٍ هداه الله وأصلح حاله؛ فاجعل جهادك وعملك خالصًا لله؛ فبالإخلاصِ في العملِ تُنال الهدايةُ وصلاحُ البالِ في الدنيا والآخرة؛ فأخلص لله في جهادك وعملك؛ فالإخلاصُ سبيلُ الهدايةِ والصلاح."}},{"n":6,"reflection":{"text":"«ويدخلهم الجنة عرفها لهم»، ويُدخِلهم الجنّةَ التي عرّفها لهم ووصفها؛ ففي هذا بيانُ جزاءِ الشهداءِ بدخولِ الجنّة؛ فاعمل لتدخل الجنّةَ التي عرّفها الله لأهلها، فالجنّةُ جزاءُ المجاهدين المخلصين، فاعمل لها بالجهادِ والإخلاص.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لدخولِ الجنّةِ بالجهادِ والإخلاص."},"action":{"text":"تأمّل جزاءَ الشهداءِ بدخولِ الجنّة: ويُدخِلهم الله الجنّةَ التي عرّفها لهم ووصفها في الدنيا فاشتاقوا إليها، أو عرّفهم منازلهم فيها فيهتدون إليها كأنهم سكّانها من قبل، لا يستدلّون عليها ولا يسألون عنها «ويدخلهم الجنة عرفها لهم»؛ ففي هذا بيانُ أنّ الله يُدخِل الشهداءَ الجنّةَ التي عرّفها لهم؛ فجزاؤهم دخولُ الجنّةِ المعروفةِ الموصوفة؛ فوالذي نفسي بيده، إنّ أحدهم أعرفُ بمنزله في الجنّةِ منه بمنزله كان في الدنيا؛ فاعمل أنت لتدخل الجنّةَ التي عرّفها الله لأهلها ووصفها؛ فالجنّةُ جزاءُ المجاهدين المخلصين والمؤمنين العاملين؛ إنّ الله اشترى من المؤمنين أنفسهم وأموالهم بأنّ لهم الجنّة؛ فاعمل للجنّةِ بالجهادِ والإخلاصِ والعملِ الصالح؛ فمن عمل لها نالها، ومن غفل عنها حُرِمها؛ فاجعل الجنّةَ غايتك، واعمل لها بالجهادِ في سبيلِ الله والإخلاصِ له؛ فبالجهادِ والعملِ الصالحِ تدخل الجنّةَ التي عرّفها الله لأهلها."}}]},{"title":"وعدُ نصرِ الله لمن نصره، وتعسُ الكافرين","range":[7,9],"theme":"الوعدُ للمؤمنين إن نصروا الله أن ينصرهم ويثبّت أقدامهم، وأنّ الذين كفروا لهم التعسُ وحبوطُ الأعمال، بسببِ كراهتهم ما أنزل الله فأحبط أعمالهم","verses":[{"n":7,"reflection":{"text":"«يا أيها الذين آمنوا إن تنصروا الله ينصركم ويثبت أقدامكم»: يا أيها المؤمنون إن تنصروا دينَ الله ينصركم على أعدائكم ويثبّت أقدامكم في القتال؛ ففي هذا بيانُ أنّ النصرَ مقرونٌ بنصرِ دينِ الله؛ فانصر دينَ الله بالعملِ والجهادِ والدعوةِ لينصرك الله، فنصرُ الله لك بقدرِ نصرك لدينه، فاجعل نصرَ الدينِ همّك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"نصرُ دينِ الله بالعملِ والجهاد، لنيلِ نصرِ الله وتثبيته."},"action":{"text":"تأمّل اقترانَ النصرِ بنصرِ الدين: يا أيها الذين آمنوا، إن تنصروا دينَ الله ورسوله بالجهادِ في سبيله، والعملِ بشرعه، والدعوةِ إليه، ونصرةِ أوليائه؛ ينصركم الله على أعدائكم، ويثبّت أقدامكم في مواطنِ القتالِ فلا تزلّ ولا تفرّ «يا أيها الذين آمنوا إن تنصروا الله ينصركم ويثبت أقدامكم»؛ ففي هذا بيانُ أنّ نصرَ الله للعبدِ مقرونٌ بنصرِ العبدِ لدينِ الله؛ فمن نصر دينَ الله نصره الله وثبّته؛ فالجزاءُ من جنسِ العمل؛ فانصر أنت دينَ الله بالعملِ بشرعه، والجهادِ في سبيله، والدعوةِ إليه، ونصرةِ الحقِّ وأهله؛ لينصرك الله على أعدائك ويثبّتك؛ ولينصرنّ الله من ينصره إنّ الله لقويٌّ عزيز؛ وكان حقًّا علينا نصرُ المؤمنين؛ فنصرُ الله لك بقدرِ نصرك لدينه؛ فمن نصر الله نصره، ومن خذل دينه خُذِل؛ فاجعل نصرَ دينِ الله همّك وشغلك؛ فبنصرِ دينِ الله تنال نصرَ الله وتثبيتَه."}},{"n":8,"reflection":{"text":"«والذين كفروا فتعسا لهم وأضل أعمالهم»، والذين كفروا فهلاكًا وخيبةً لهم، وأبطل الله أعمالهم؛ ففي هذا بيانُ خيبةِ الكافرين وحبوطِ أعمالهم؛ فاحذر الكفرَ الذي يورث التعسَ وحبوطَ العمل، فآمن واعمل صالحًا لتفوز، فالكفرُ خيبةٌ وهلاكٌ وحبوطٌ للعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ والعملُ الصالحُ للفوز، والحذرُ من التعسِ بالكفر."},"action":{"text":"تأمّل خيبةَ الكافرين: والذين كفروا بالله ورسوله، فتعسًا وهلاكًا وخيبةً وشقاءً لهم؛ وأضلَّ الله أعمالهم وأبطلها فلا تنفعهم «والذين كفروا فتعسا لهم وأضل أعمالهم»؛ ففي هذا بيانُ أنّ الكافرين لهم التعسُ والهلاكُ والخيبة، وأنّ أعمالهم حابطة؛ فقابل بين نصرِ المؤمنين وتثبيتهم، وبين تعسِ الكافرين وحبوطِ أعمالهم؛ فالتعسُ ضدُّ السعادةِ والفلاح؛ فاحذر الكفرَ الذي يورث التعسَ والهلاكَ وحبوطَ العمل؛ فآمن بالله ورسوله، واعمل صالحًا لتفوز بالسعادةِ والنصر؛ فالكفرُ خيبةٌ وهلاكٌ في الدنيا والآخرة؛ خسر الدنيا والآخرة ذلك هو الخسرانُ المبين؛ فمن آمن سعد ونُصِر، ومن كفر تعس وخاب؛ فاجعل إيمانك وعملك الصالحَ سبيلَ فوزك؛ فبالإيمانِ تسعد، وبالكفرِ تتعس؛ فاجتنب الكفرَ وأسبابه، والزم الإيمانَ والعملَ الصالح."}},{"n":9,"reflection":{"text":"«ذلك بأنهم كرهوا ما أنزل الله فأحبط أعمالهم»: ذلك التعسُ والحبوطُ لأنهم كرهوا ما أنزل الله من القرآنِ والشرع، فأحبط أعمالهم؛ ففي هذا بيانُ أنّ كراهةَ ما أنزل الله سببُ الحبوط؛ فأحبب ما أنزل الله وارضَ به، فكراهةُ شرعِ الله تحبط العمل، فاجعل قلبك محبًّا لما أنزل الله راضيًا به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"محبّةُ ما أنزل الله والرضا به، والحذرُ من كراهةِ شرعه."},"action":{"text":"تأمّل بيانَ سببِ الحبوط: ذلك التعسُ وحبوطُ الأعمالِ الذي حلَّ بالكافرين، سببه أنهم كرهوا ما أنزل الله من القرآنِ والوحيِ والشرائع، فلم يقبلوه ولم يرضوا به؛ فأحبط الله أعمالهم وأبطلها جزاءَ كراهتهم «ذلك بأنهم كرهوا ما أنزل الله فأحبط أعمالهم»؛ ففي هذا بيانُ أنّ كراهةَ ما أنزل الله من الوحيِ والشرعِ سببٌ لحبوطِ العملِ والتعس؛ فكراهةُ شرعِ الله من أعظمِ ما يحبط العمل؛ فاحذر أن تكره شيئًا ممّا أنزل الله من القرآنِ والسنّةِ والأحكام؛ بل أحبب ما أنزل الله كلَّه، وارضَ به، وانقد له؛ فمن كره ما أنزل الله ولو حكمًا واحدًا خطر على إيمانه؛ ومن يبتغِ غيرَ الإسلامِ دينًا فلن يُقبَل منه؛ فاجعل قلبك محبًّا لما أنزل الله، راضيًا به، منقادًا له؛ فمن أحبّ شرعَ الله ورضي به نفعه عمله، ومن كرهه حبط عمله؛ فاحذر كراهةَ شيءٍ من دينِ الله؛ والزم محبّةَ ما أنزله والرضا به والانقيادَ له."}}]},{"title":"الاعتبارُ بالأمم، وولايةُ الله للمؤمنين، ومقابلةُ الجزاء","range":[10,15],"theme":"الحثُّ على السيرِ والاعتبارِ بعاقبةِ المكذّبين، وأنّ الله مولى المؤمنين والكافرين لا مولى لهم، ومقابلةُ جنّاتِ المؤمنين بتمتّعِ الكافرين كالأنعامِ ومثواهم النار، وإهلاكِ القرى الأقوى، والفرقِ بين صاحبِ البيّنةِ وصاحبِ الهوى، ومثلِ الجنّةِ بأنهارها الأربعةِ مقابلَ حميمِ النار","verses":[{"n":10,"reflection":{"text":"«أفلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم دمر الله عليهم وللكافرين أمثالها»: أفلم يسر الكفّارُ في الأرضِ فينظروا كيف كانت عاقبةُ المكذّبين قبلهم؟ دمّر الله عليهم، وللكافرين أمثالُ تلك العاقبة؛ ففي هذا الحثُّ على الاعتبارِ بمصارعِ الأمم؛ فاعتبر بعواقبِ المكذّبين قبلك، فالكفرُ يورث الدمار، فاحذر أن يصيبك ما أصابهم، واتّعظ بمصارعهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الأمم، والحذرُ من عاقبةِ الكفر."},"action":{"text":"تأمّل الحثَّ على الاعتبار: أفلم يسر هؤلاء المكذّبون في الأرضِ فينظروا بعقولهم كيف كانت عاقبةُ الأممِ المكذّبةِ من قبلهم؟ دمّر الله عليهم مساكنهم وأهلكهم بذنوبهم؛ وللكافرين من قريشٍ وغيرهم أمثالُ تلك العاقبةِ إن استمرّوا على كفرهم «أفلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم دمر الله عليهم وللكافرين أمثالها»؛ ففي هذا الحثُّ على السيرِ والنظرِ والاعتبارِ بمصارعِ الأممِ المكذّبة، والتحذيرُ من مثلِ عاقبتهم؛ فأهلك الله المكذّبين قبلهم، وتوعّد الكافرين بمثلِ ذلك؛ فاعتبر أنت بعواقبِ المكذّبين والكافرين قبلك؛ وكيف دمّر الله عليهم بكفرهم؛ قد خلت من قبلكم سننٌ فسيروا في الأرضِ فانظروا كيف كان عاقبةُ المكذّبين؛ فالكفرُ والتكذيبُ يورثان الدمارَ والهلاك؛ فاحذر أن يصيبك ما أصابهم بكفرك أو معصيتك؛ فمن اتّعظ بمصارعِ الأممِ نجا، ومن غفل عنها هلك؛ فاجعل من عواقبِ المكذّبين عبرةً تحملك على الإيمانِ والطاعة."}},{"n":11,"reflection":{"text":"«ذلك بأن الله مولى الذين آمنوا وأن الكافرين لا مولى لهم»: ذلك النصرُ والدمارُ لأنّ الله وليُّ المؤمنين وناصرهم، وأنّ الكافرين لا وليَّ لهم ولا ناصر؛ ففي هذا بيانُ ولايةِ الله للمؤمنين وخذلانِ الكافرين؛ فاطلب ولايةَ الله بالإيمانِ والطاعة، فمن كان الله مولاه فلا يُغلَب، ومن لا مولى له خُذِل، فاجعل الله مولاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ ولايةِ الله بالإيمانِ والطاعة، وإدراكُ أنّ الكافرَ لا ناصرَ له."},"action":{"text":"تأمّل ولايةَ الله للمؤمنين: ذلك النصرُ للمؤمنين والدمارُ على الكافرين، سببه أنّ الله مولى الذين آمنوا وناصرهم وحافظهم ومتولّي أمورهم؛ وأنّ الكافرين لا مولى لهم ينصرهم أو يتولّى أمورهم؛ فهم مخذولون «ذلك بأن الله مولى الذين آمنوا وأن الكافرين لا مولى لهم»؛ ففي هذا بيانُ أنّ الله وليُّ المؤمنين وناصرهم، وأنّ الكافرين لا وليَّ لهم؛ فبولايةِ الله نُصِر المؤمنون، وبعدمِ الناصرِ خُذِل الكافرون؛ فاطلب أنت ولايةَ الله بالإيمانِ والعملِ الصالحِ والطاعة؛ الله وليُّ الذين آمنوا يخرجهم من الظلماتِ إلى النور، والذين كفروا أولياؤهم الطاغوت؛ فمن كان الله مولاه ووليّه فلا يُغلَب ولا يُخذَل؛ ومن لا مولى له من الكافرين مخذولٌ خاسر؛ نِعم المولى ونِعم النصير؛ فاجعل الله مولاك ووليّك بالإيمانِ والطاعةِ والتوكّلِ عليه؛ فبولايةِ الله تُنصَر وتُحفَظ، وبفقدها تُخذَل وتخسر؛ فالزم ما يجعلك في ولايةِ الله من الإيمانِ والتقوى."}},{"n":12,"reflection":{"text":"«إن الله يدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحتها الأنهار والذين كفروا يتمتعون ويأكلون كما تأكل الأنعام والنار مثوى لهم»: إنّ الله يُدخِل المؤمنين العاملين جنّاتٍ تجري تحتها الأنهار، والكافرون يتمتّعون ويأكلون كالأنعامِ لا همَّ لهم إلا شهواتهم، والنارُ مقامهم؛ ففي هذا المقابلةُ بين همّةِ المؤمنِ وهمّةِ الكافر؛ فاجعل همّتك الآخرةَ لا مجرّدَ التمتّعِ كالأنعام، فالمؤمنُ يعمل للجنّة، والكافرُ يعيش لبطنه، فارفع همّتك للآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"رفعُ الهمّةِ للآخرةِ والعملُ للجنّة، لا العيشُ للشهواتِ كالأنعام."},"action":{"text":"تأمّل المقابلةَ بين همّةِ المؤمنِ والكافر: إنّ الله يُدخِل الذين آمنوا وعملوا الصالحاتِ جنّاتٍ تجري من تحت أشجارها وقصورها الأنهار، جزاءَ إيمانهم وعملهم؛ والذين كفروا يتمتّعون في الدنيا بشهواتها، ويأكلون كما تأكل الأنعامُ في غفلةٍ لا همَّ لهم إلا بطونهم وفروجهم، لا يفكّرون في عاقبةٍ ولا آخرة؛ والنارُ مثوًى ومقامٌ لهم «إن الله يدخل الذين آمنوا وعملوا الصالحات جنات... والنار مثوى لهم»؛ ففي هذا المقابلةُ بين همّةِ المؤمنِ الذي يعمل للجنّة، وهمّةِ الكافرِ الذي يعيش للتمتّعِ كالأنعام؛ فالمؤمنُ يعمل لآخرته، والكافرُ لبطنه وشهوته؛ فاجعل همّتك الآخرةَ والعملَ للجنّة، لا مجرّدَ التمتّعِ والأكلِ كالأنعام؛ أولئك كالأنعامِ بل هم أضلّ؛ يتمتّعون ويأكلون وتلهيهم الأمل؛ فلا تعش لبطنك وشهوتك كالبهائم؛ بل ارفع همّتك إلى الآخرةِ والعملِ لها؛ فمن عمل للجنّةِ نالها، ومن عاش للشهواتِ كان مثواه النار؛ فاجعل همّتك عاليةً للآخرة، لا دنيّةً للشهواتِ العاجلة."}},{"n":13,"reflection":{"text":"«وكأين من قرية هي أشد قوة من قريتك التي أخرجتك أهلكناهم فلا ناصر لهم»، وكم من قريةٍ أشدَّ قوّةً من مكّةَ التي أخرجتك، أهلكناهم فلم يجدوا ناصرًا؛ ففي هذا تسليةٌ للنبيِّ ووعيدٌ لمن أخرجه؛ فاعلم أنّ الله يهلك الأقوياءَ المكذّبين فلا ناصرَ لهم، فلا تحزن على أذى أهلِ الباطل، فالله ينتقم من الظالمين ولو كانوا أقوياء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بنصرِ الله وانتقامِه من الظالمين، وعدمُ الحزنِ على أذى الباطل."},"action":{"text":"تأمّل التسليةَ والوعيد: وكم من قريةٍ كانت أشدَّ قوّةً وأكثرَ أموالًا وأعوانًا من قريتك، مكّةَ، التي أخرجك أهلها؛ أهلكناهم بذنوبهم وتكذيبهم، فلم يجدوا ناصرًا ينصرهم أو يدفع عنهم عذابنا «وكأين من قرية هي أشد قوة من قريتك التي أخرجتك أهلكناهم فلا ناصر لهم»؛ ففي هذا تسليةٌ للنبيِّ ﷺ الذي أخرجه أهلُ مكّة، ووعيدٌ لهم بالإهلاكِ كما أُهلِك من قبلهم؛ فالله أهلك من هو أشدُّ منهم قوّة، فلا يُعجِزه إهلاكُ قريش؛ فاعلم أنّ الله يهلك الأقوياءَ المكذّبين الظالمين فلا ناصرَ لهم؛ فكم أهلكنا من قبلهم من قرنٍ هم أشدُّ منهم بطشًا؛ فلا تحزن، أيها المؤمنُ، على ما يصيبك من أذى أهلِ الباطلِ وإخراجهم لك؛ فإنّ الله ناصرك ومنتقمٌ من عدوّك؛ ولا تحسبنّ الله غافلًا عمّا يعمل الظالمون؛ فالله ينتقم من الظالمين ولو كانوا أقوياء؛ فمن وثق بنصرِ الله واحتسب أذى الباطلِ صبر ونُصِر؛ فاجعل ثقتك بنصرِ الله وانتقامِه من الظالمين؛ فلا تحزن على أذى أهلِ الباطل، فالعاقبةُ لك."}},{"n":14,"reflection":{"text":"«أفمن كان على بينة من ربه كمن زين له سوء عمله واتبعوا أهواءهم»: أفمن كان على حجّةٍ وبصيرةٍ من ربّه كمن زُيِّن له سوءُ عمله واتّبع هواه؟ ففي هذا المقابلةُ بين صاحبِ البصيرةِ وصاحبِ الهوى؛ فكن على بيّنةٍ من ربّك بالعلمِ والبصيرة، ولا تتّبع هواك فيُزيَّن لك سوءُ عملك، فصاحبُ البصيرةِ يرى الحقَّ وصاحبُ الهوى يرى الباطلَ حسنًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الكونُ على بيّنةٍ من الله بالبصيرة، وتركُ اتّباعِ الهوى."},"action":{"text":"تأمّل المقابلةَ بين صاحبِ البصيرةِ وصاحبِ الهوى: أفمن كان على بيّنةٍ وحجّةٍ وبصيرةٍ من ربّه في دينه وعمله، وهو المؤمنُ المتّبعُ للحق، كمن زُيِّن له سوءُ عمله فرآه حسنًا، واتّبعوا أهواءهم بلا هدًى؟ لا يستويان «أفمن كان على بينة من ربه كمن زين له سوء عمله واتبعوا أهواءهم»؛ ففي هذا المقابلةُ بين المؤمنِ صاحبِ البصيرةِ الذي يرى الحقَّ على حقيقته، والكافرِ الذي زُيِّن له سوءُ عمله فاتّبع هواه؛ فشتّان بينهما؛ فالأوّلُ على نورٍ وبصيرة، والثاني في ظلمةٍ وهوى؛ فكن أنت على بيّنةٍ من ربّك بالعلمِ النافعِ والبصيرةِ في الدين؛ واعمل على هدًى ونور؛ ولا تتّبع هواك فيُزيَّن لك سوءُ عملك فتراه حسنًا؛ أفمن زُيِّن له سوءُ عمله فرآه حسنًا؛ قل هل ننبّئكم بالأخسرين أعمالًا... وهم يحسبون أنهم يحسنون صنعًا؛ فصاحبُ البصيرةِ يرى الحقَّ ويتّبعه، وصاحبُ الهوى يرى الباطلَ حسنًا فيتّبعه؛ فمن كان على بيّنةٍ اهتدى، ومن اتّبع هواه ضلّ وهو يحسب أنه محسن؛ فاجعل عملك على بيّنةٍ وبصيرةٍ من ربّك، لا على هوًى وتزيين."}},{"n":15,"reflection":{"text":"«مثل الجنة التي وعد المتقون فيها أنهار من ماء غير آسن وأنهار من لبن لم يتغير طعمه وأنهار من خمر لذة للشاربين وأنهار من عسل مصفى ولهم فيها من كل الثمرات ومغفرة من ربهم كمن هو خالد في النار وسقوا ماء حميما فقطع أمعاءهم»: صفةُ الجنّةِ الموعودةِ للمتّقين: أنهارٌ من ماءٍ لم يتغيّر، ولبنٍ لم يتغيّر طعمه، وخمرٍ لذيذةٍ، وعسلٍ مصفًّى، ولهم كلُّ الثمراتِ ومغفرة؛ أكمن هو خالدٌ في النارِ يُسقى ماءً حارًّا يقطّع أمعاءهم؟ ففي هذا المقابلةُ بين نعيمِ المتّقين وعذابِ الكافرين؛ فاعمل بالتقوى لتنال نعيمَ الجنّة، فشتّان بين نعيمِ المتّقين وعذابِ الكافرين، فاختر لنفسك التقوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ بالتقوى لنيلِ نعيمِ الجنّة، وتصوّرُ الفرقِ بين الجزاءين."},"action":{"text":"تأمّل المقابلةَ بين نعيمِ المتّقين وعذابِ الكافرين: صفةُ الجنّةِ العجيبةِ التي وعد الله بها المتّقين: فيها أنهارٌ من ماءٍ غيرِ آسنٍ، لم يتغيّر ريحه ولا طعمه ،، وأنهارٌ من لبنٍ لم يتغيّر طعمه، وأنهارٌ من خمرٍ لذّةٍ للشاربين لا غولَ فيها ولا صداع، وأنهارٌ من عسلٍ مصفًّى؛ ولهم فيها من كلِّ الثمراتِ التي يشتهون، ومغفرةٌ من ربّهم لذنوبهم؛ أفمن هو في هذا النعيمِ كمن هو خالدٌ في النار، يُسقى ماءً حميمًا شديدَ الحرارةِ فيقطّع أمعاءهم؟ لا يستويان «مثل الجنة التي وعد المتقون... وسقوا ماء حميما فقطع أمعاءهم»؛ ففي هذا المقابلةُ العظيمةُ بين نعيمِ المتّقين في الجنّةِ وأنهارها الأربعة، وعذابِ الكافرين في النارِ وحميمها؛ فشتّان بين الجزاءين؛ فاعمل أنت بالتقوى، فعلِ المأموراتِ وتركِ المحظورات، لتنال نعيمَ الجنّةِ وأنهارها؛ فالجنّةُ جزاءُ المتّقين؛ وأزلفتِ الجنّةُ للمتّقين؛ وتصوّر الفرقَ بين نعيمِ المتّقين وعذابِ الكافرين لتختار لنفسك؛ فمن اتّقى نال النعيم، ومن كفر خُلِّد في العذاب؛ فاجعل التقوى سبيلك لتنال نعيمَ الجنّة، وتنجو من عذابِ النار."}}]},{"title":"حالُ المنافقين في الاستماع، والأمرُ بالتوحيدِ والاستغفار","range":[16,19],"theme":"حالُ المنافقين الذين يستمعون بلا انتفاعٍ فطُبِع على قلوبهم، مقابلَ المهتدين الذين يزدادون هدًى وتقوى، والتحذيرُ من بغتةِ الساعةِ وقد جاءت أشراطها، والأمرُ بالعلمِ أنه لا إله إلا الله وبالاستغفارِ للنفسِ وللمؤمنين","verses":[{"n":16,"reflection":{"text":"«ومنهم من يستمع إليك حتى إذا خرجوا من عندك قالوا للذين أوتوا العلم ماذا قال آنفا أولئك الذين طبع الله على قلوبهم واتبعوا أهواءهم»، ومن المنافقين من يستمع إليك، فإذا خرجوا قالوا للعلماءِ استهزاءً: ماذا قال آنفًا؟ أولئك طبع الله على قلوبهم واتّبعوا أهواءهم؛ ففي هذا بيانُ حالِ المنافقين في الاستماعِ بلا فهمٍ ولا انتفاع؛ فاحذر أن تستمع للحقِّ بلا قلبٍ واعٍ، فاستمع بقلبٍ حاضرٍ منتفع، فالطبعُ على القلبِ عاقبةُ اتّباعِ الهوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستماعُ للحقِّ بقلبٍ واعٍ منتفع، والحذرُ من اتّباعِ الهوى."},"action":{"text":"تأمّل حالَ المنافقين في الاستماع: ومن المنافقين من يستمع إليك، يا محمدُ، وأنت تتلو القرآنَ وتعظ، لكن بلا قصدِ فهمٍ ولا انتفاع؛ حتى إذا خرجوا من عندك قالوا للعلماءِ من الصحابةِ استهزاءً وإعراضًا: ماذا قال محمدٌ آنفًا الساعة؟ تجاهلًا وإعراضًا؛ أولئك هم الذين طبع الله على قلوبهم فلا يعقلون خيرًا، واتّبعوا أهواءهم فأعرضوا عن الحق «ومنهم من يستمع إليك حتى إذا خرجوا من عندك قالوا للذين أوتوا العلم ماذا قال آنفا أولئك الذين طبع الله على قلوبهم واتبعوا أهواءهم»؛ ففي هذا بيانُ حالِ المنافقين الذين يستمعون بلا فهمٍ ولا انتفاع، وأنّ سببه الطبعُ على قلوبهم واتّباعُ أهوائهم؛ فاستمعوا بآذانهم دون قلوبهم؛ فاحذر أنت أن تستمع للحقِّ والقرآنِ بلا قلبٍ واعٍ ولا نيّةِ انتفاع؛ فاستمع بقلبٍ حاضرٍ متدبّرٍ منتفع؛ إنّ في ذلك لذكرى لمن كان له قلبٌ أو ألقى السمعَ وهو شهيد؛ واحذر اتّباعَ الهوى الذي يورث الطبعَ على القلب؛ فمن استمع بقلبٍ واعٍ انتفع واهتدى، ومن استمع بلا قلبٍ طُبِع عليه؛ فاجعل استماعك للحقِّ بقلبٍ حاضرٍ منتفع، لا كاستماعِ المنافقين."}},{"n":17,"reflection":{"text":"«والذين اهتدوا زادهم هدى وآتاهم تقواهم»، والذين اهتدوا إلى الحقِّ زادهم الله هدًى، وألهمهم تقواهم ووفّقهم لها؛ ففي هذا بيانُ أنّ الهدايةَ تزيد بالعمل؛ فاهتدِ واعمل بالحقِّ يزدك الله هدًى وتقوى، فالهدايةُ تنمو بالعمل، فاعمل بما علمت يزدك الله علمًا وهدى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ بالحقِّ لزيادةِ الهدى والتقوى، والاهتداءُ نموٌّ لا جمود."},"action":{"text":"تأمّل زيادةَ الهدى للمهتدين: والذين اهتدوا إلى الحقِّ واتّبعوه، زادهم الله هدًى على هداهم بأن وفّقهم للعملِ بما علموا فزادهم علمًا وإيمانًا؛ وآتاهم وألهمهم تقواهم ووفّقهم لها «والذين اهتدوا زادهم هدى وآتاهم تقواهم»؛ ففي هذا بيانُ أنّ الله يزيد المهتدين هدًى، ويؤتيهم التقوى، جزاءَ اهتدائهم وعملهم؛ فالهدايةُ تزيد بالعملِ بالحق؛ فمقابلَ المنافقين الذين طُبِع على قلوبهم، المهتدون يزدادون هدًى؛ فاهتدِ أنت إلى الحقِّ واعمل به، يزدك الله هدًى وتقوى؛ ويزيد الله الذين اهتدوا هدًى؛ وإذا تُليت عليهم آياته زادتهم إيمانًا؛ ومن يؤمن بالله يهدِ قلبه؛ فالهدايةُ تنمو بالعملِ بها، والعلمُ يزيد بالعملِ به؛ من عمل بما علم أورثه الله علمَ ما لم يعلم؛ فاعمل بما علمت من الحقِّ يزدك الله علمًا وهدًى وتقوى؛ فمن عمل بهداه زاده الله هدًى، ومن أعرض نُزِع منه؛ فاجعل العملَ بالحقِّ سبيلَ زيادةِ هداك وتقواك."}},{"n":18,"reflection":{"text":"«فهل ينظرون إلا الساعة أن تأتيهم بغتة فقد جاء أشراطها فأنى لهم إذا جاءتهم ذكراهم»: فهل ينتظر المكذّبون إلا الساعةَ أن تأتيهم فجأة؟ فقد جاءت علاماتها، فكيف يتذكّرون إذا جاءتهم والتذكّرُ لا ينفع؟ ففي هذا التحذيرُ من بغتةِ الساعةِ والحثُّ على المبادرة؛ فبادر بالتوبةِ والعملِ قبل بغتةِ الساعة، فالتذكّرُ عند مجيئها لا ينفع، فاغتنم المهلةَ قبل فواتها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالتوبةِ والعملِ قبل بغتةِ الساعة."},"action":{"text":"تأمّل التحذيرَ من بغتةِ الساعة: فهل ينتظر هؤلاء المكذّبون المعرضون إلا الساعةَ أن تأتيهم فجأةً وهم غافلون؟ فقد جاءت علاماتها وأشراطها، ومنها بعثةُ النبيِّ ﷺ فهو أوّلُ أشراطها ،؛ فأنّى لهم وكيف ينفعهم التذكّرُ والاتّعاظُ إذا جاءتهم الساعة؟ فالتذكّرُ حينئذٍ لا ينفع «فهل ينظرون إلا الساعة أن تأتيهم بغتة فقد جاء أشراطها فأنى لهم إذا جاءتهم ذكراهم»؛ ففي هذا التحذيرُ من مجيءِ الساعةِ بغتة، وأنّ علاماتها قد بدأت، وأنّ التذكّرَ عند مجيئها لا ينفع؛ فالساعةُ قريبةٌ وأشراطها ظاهرة؛ فبادر أنت بالتوبةِ والعملِ الصالحِ قبل أن تأتيَ الساعةُ بغتة؛ اقتربت الساعةُ وانشقّ القمر؛ هل ينظرون إلا الساعةَ أن تأتيهم بغتةً وهم لا يشعرون؛ فالتذكّرُ والاتّعاظُ عند مجيءِ الساعةِ أو حضورِ الموتِ لا ينفع؛ يومئذٍ يتذكّر الإنسانُ وأنّى له الذكرى؛ فاغتنم مهلةَ حياتك بالتوبةِ والعملِ قبل بغتةِ الساعة؛ فمن بادر بالعملِ نجا، ومن سوّف حتى فاجأته الساعةُ خسر؛ فبادر بالتوبةِ والعملِ الصالحِ الآن قبل فواتِ الأوان."}},{"n":19,"reflection":{"text":"«فاعلم أنه لا إله إلا الله واستغفر لذنبك وللمؤمنين والمؤمنات والله يعلم متقلبكم ومثواكم»: فاعلم أنه لا معبودَ بحقٍّ إلا الله، واستغفر لذنبك وللمؤمنين والمؤمنات، والله يعلم تصرّفكم ومستقرّكم؛ ففي هذا الأمرُ بالعلمِ بالتوحيدِ والاستغفار؛ فاعلم توحيدَ الله علمًا يورث العمل، واستغفر لذنبك وللمؤمنين، فالعلمُ بالتوحيدِ أصلُ الدين، والاستغفارُ دأبُ الصالحين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العلمُ بالتوحيدِ والعملُ به، والمداومةُ على الاستغفارِ للنفسِ وللمؤمنين."},"action":{"text":"تأمّل الأمرَ بالعلمِ بالتوحيدِ والاستغفار: فاعلم، يا محمدُ ويا كلَّ مكلّف، علمًا يقينيًّا يثمر العملَ والإخلاص، أنه لا إله إلا الله، لا معبودَ بحقٍّ سواه؛ واستغفر لذنبك وللمؤمنين والمؤمنات؛ والله يعلم متقلّبكم في نهاركم وتصرّفكم في معايشكم، ومثواكم ومستقرّكم بالليلِ وفي قبوركم؛ فراقبوه «فاعلم أنه لا إله إلا الله واستغفر لذنبك وللمؤمنين والمؤمنات والله يعلم متقلبكم ومثواكم»؛ ففي هذا الأمرُ بالعلمِ بالتوحيد، وهو أصلُ الدين وأعظمُ العلوم، والأمرُ بالاستغفارِ للنفسِ وللمؤمنين؛ فبدأ بالعلمِ بالتوحيدِ لأنه أساسُ كلِّ عملٍ وقول؛ فاعلم توحيدَ الله علمًا راسخًا يورث العملَ والإخلاصَ والدعوةَ إليه؛ فالعلمُ بالتوحيدِ أوّلُ واجبٍ وأعظمُ العلوم؛ واعمل بمقتضاه من إفرادِ الله بالعبادة؛ ثم داوم على الاستغفارِ لذنبك وللمؤمنين والمؤمنات؛ فالاستغفارُ دأبُ الأنبياءِ والصالحين؛ وكان النبيُّ ﷺ يستغفر في المجلسِ الواحدِ مائةَ مرّة؛ واعلم أنّ الله يعلم أحوالك كلَّها فراقبه؛ فمن علم التوحيدَ وعمل به واستغفر سعد، ومن جهله أو أعرض خسر؛ فاجعل العلمَ بالتوحيدِ والاستغفارَ دأبك."},"qadiyya":{"title":"قضيّةُ «فاعلمْ»: لماذا أمر اللهُ نبيَّه أن يعلم ما هو عالمٌ به؟","question":"في سورة محمّدٍ خطابٌ للنبيِّ ﷺ: «**فاعلمْ أنّه لا إله إلّا الله**».\n**وها هنا سؤالٌ يعرض لكلّ من تأمّل**: النبيُّ ﷺ **يعلم** ذلك، وهو الذي بُعث به وجاهد فيه عشرين سنة. **فما معنى أن يُؤمر بأن يعلمه؟**\nثمّ في الآية ترتيبٌ لا يُغفَل: **«فاعلمْ» أوّلًا، ثمّ «واستغفرْ» ثانيًا.** **العلمُ قبل العمل.**\nفالقضيّة: **ما «العلم» المأمورُ به ها هنا؟ وهل هو معلومةٌ تُحفظ أم شيءٌ آخر؟ وكيف يُطلب؟**","background":"ولا يُفهم هذا حتى نفرّق بين ثلاثة أشياء من الصفر:\n**الأوّل: العلمُ بالشيء**، وهو أن يعرفه المرءُ معرفةً صحيحة.\n**والثاني: الإقرارُ به**، وهو أن يعترف بأنّه حقّ.\n**والثالث: العملُ بمقتضاه.**\n**وقد يجتمع الأوّلان ويتخلّف الثالث**؛ فإنّ إبليسَ يعلم أنّ الله ربُّه ويقرّ به، ولم ينفعه.\n**وأمّا «لا إله إلّا الله» فمعناها**: لا معبودَ بحقٍّ إلّا الله. **وليست نفيًا لوجود آلهةٍ يعبدها الناس**، فتلك موجودةٌ تُعبد، **إنّما هي نفيٌ لاستحقاقها العبادة.**","what_happened":"**أمّا معنى «العلم» في الآية فقد حرّره السعديُّ في أوّل كلمة.** قال: «**العلم لا بدّ فيه من إقرار القلب ومعرفته، بمعنى ما طُلب منه علمُه، وتمامُه أن يعمل بمقتضاه**».\n**فجعله ثلاثةَ أركان**: معرفةٌ، وإقرارُ قلب، **وعملٌ هو تمامُه**. **فالعلمُ الذي يُؤمَر به ليس حفظَ عبارة؛ إنّه معرفةٌ يصدّقها القلبُ ثمّ يتبعها الجسد.**\n**ثمّ قرّر حكمَه**: «**وهذا العلم الذي أمر الله به، وهو العلم بتوحيد الله، فرضُ عينٍ على كلِّ إنسان، لا يسقط عن أحد، كائنًا من كان، بل كلٌّ مضطرٌّ إلى ذلك**».\n**ثمّ صنع ما هو أنفع من التقرير: فتح الطريقَ إليه.** فقال: «**والطريقُ إلى العلم بأنّه لا إله إلّا هو أمور**»، وعدّها خمسةً:\n**الأوّل، وهو أعظمُها**: «**تدبّرُ أسمائه وصفاته، وأفعاله الدالّة على كماله وعظمته وجلالته**»، «فإنّها توجب بذلَ الجهد في التألّه له».\n**والثاني**: «**العلمُ بأنّه تعالى المنفردُ بالخلق والتدبير، فيُعلم بذلك أنّه المنفردُ بالألوهيّة**».\n**والثالث**: «**العلمُ بأنّه المنفردُ بالنعم الظاهرة والباطنة، الدينيّة والدنيويّة**»، «فإنّ ذلك يوجب تعلّقَ القلب به ومحبّتَه».\n**والرابع**: ما يُرى ويُسمع من ثواب الله لأوليائه القائمين بتوحيده، ومن عقوبته لأعدائه المشركين به.\n**والخامس**: «**معرفةُ أوصاف الأوثان والأنداد التي عُبدت مع الله**»، وأنّها «ناقصةٌ من جميع الوجوه، فقيرةٌ بالذات، لا تملك لنفسها ولا لعابديها نفعًا ولا ضرًّا».","the_verdict":"**فالحاصلُ أنّ الأمرَ في «فاعلمْ» ليس أمرًا بتحصيل خبرٍ جديد، بل بتجديد علمٍ قائمٍ وترقيته.**\nفإنّ العلم بهذه الكلمة **يزيد وينقص**؛ وليس كعلمك بأنّ اثنين واثنين أربعة، تعلمه مرّةً فلا يزيد. **بل كلّما تدبّرتَ اسمًا من أسمائه، أو رأيتَ أثرًا من آثار ربوبيّته، أو تأمّلتَ عجزَ ما يُعبد من دونه، ازددتَ علمًا بها.** **ولهذا كان الأمرُ بها قائمًا وإن كان المأمورُ أعلمَ الخلق بها ﷺ.**\n**وأمّا ترتيبُ الآية فمعلَمٌ في بابه**: «فاعلمْ» ثمّ «واستغفرْ». **فالعلمُ مقدَّمٌ على العمل**، وقد جعل السعديُّ العملَ **تمامَ العلم** لا شيئًا أجنبيًّا عنه. **فمن عمل بلا علمٍ لم يأمن أن يفسد عملُه، ومن علم ولم يعمل فعلمُه ناقص.**\n**⭐ وأنفعُ ما في هذا التحرير أنّ السعديَّ لم يجعل التوحيد شيئًا يُتلقّى ويُسلَّم فحسب، بل جعل له خمسةَ طرق يُسلك فيها.** وثلاثةٌ منها **نظرٌ في المعلوم**: في الأسماء والصفات، وفي انفراده بالخلق، وفي انفراده بالنعم. **وواحدٌ منها نظرٌ في التاريخ والواقع.** **وواحدٌ نظرٌ فيما يُعبد من دون الله، وهو أعجبها**: أن تعرف التوحيدَ من جهة **نقص ما سواه**.\n**فالمقصودُ أنّ هذه الكلمة تُطلب بالنظر كما تُتلقّى بالخبر؛ والذي يقولها ولا ينظر فيها يقولها بلسانه فقط.**","for_you":"**فأمّا الذي تخرج به فثلاثة:**\n**الأوّل: لا تحسبْ توحيدَك رصيدًا ثابتًا.** فإنّ هذه الكلمة **علمٌ يزيد وينقص**، وقد أُمر بها أعلمُ الخلق. **فاسأل: متى آخرُ مرّةٍ ازددتُ فيها علمًا بربّي؟** فإن لم تكن تذكر **فأنت في نقصان، وإن كنتَ تحفظ الكلمةَ منذ الصغر.**\n**والثاني: خذ طريقًا من الخمسة هذا الأسبوع.** أيسرُها وأعظمُها الأوّل: **اقرأ في اسمٍ واحدٍ من أسماء الله وتدبّره حتى تعرف أثرَه في حالك.** أو خذ الثالث: **اجلس واعدد نعمَه عليك، ظاهرةً وباطنة، حتى يمتلئ القلبُ محبّة**. **فهذه أعمالٌ تُجدَول لا مواعظُ تُسمع.**\n**والثالث: أتبعِ العلمَ عملًا في يومه.** فقد جعل السعديُّ العملَ **تمامَ العلم**. **وأوّلُ ما أُمر به النبيُّ ﷺ بعد «فاعلمْ» هو «واستغفرْ»**. **فإذا ازددتَ علمًا بعظمة ربّك فأوّلُ ما ينبغي أن يتحرّك فيك الاستغفارُ، لا الفخرُ بما علمت.** **والذي يزداد علمًا فيزداد تيهًا لم يزدد علمًا؛ إنّما ازداد معلومات.**","grade":"ma'thur","source":"تحريرُ السعديّ لمعنى العلم («العلم لا بد فيه من إقرار القلب ومعرفته، بمعنى ما طلب منه علمه، وتمامه أن يعمل بمقتضاه»)، وحكمُه («وهذا العلم الذي أمر الله به، وهو العلم بتوحيد الله، فرض عين على كل إنسان، لا يسقط عن أحد، كائنا من كان»)، والطرقُ الخمسة بنصّها («أحدها بل أعظمها: تدبر أسمائه وصفاته، وأفعاله الدالة على كماله وعظمته وجلالته»، «الثاني: العلم بأنه تعالى المنفرد بالخلق والتدبير، فيعلم بذلك أنه المنفرد بالألوهية»، «الثالث: العلم بأنه المنفرد بالنعم الظاهرة والباطنة»، والرابعُ في ثوابه لأوليائه وعقوبته لأعدائه، «الخامس: معرفة أوصاف الأوثان والأنداد التي عبدت مع الله»): كلُّها بنصّها في تفسير السعديّ (٤٧:١٩).","honesty":"وممّا يجب أن يُقال:\n**الطرقُ الخمسةُ عدَّها السعديُّ ورقّمها بنفسه**، فالعددُ والترتيبُ له لا لنا.\n**وأمّا قولُنا إنّ العلم بهذه الكلمة يزيد وينقص فهو لازمُ كلامه في الطرق الخمسة، لا نصٌّ له في هذا الموضع بلفظه.**\n**وأمّا مسألةُ زيادة الإيمان ونقصانه على وجهها ففي كتب الاعتقاد**، ولم نتعرّض لها.\n**وأمّا ذكرُنا لإبليس في التمهيد فتمثيلٌ منّا للفرق بين العلم والعمل، لا نقلٌ عن إمامٍ في هذا الموضع.**"}}]},{"title":"المنافقون وكراهيةُ القتال، والتحذيرُ من الإفسادِ والقطيعة","range":[20,23],"theme":"شوقُ المؤمنين لسورةِ القتالِ مقابلَ جزعِ مرضى القلوبِ منها كنظرِ المغشيِّ عليه، وأنّ الأولى بهم طاعةٌ وصدقٌ مع الله، والتحذيرُ من الإفسادِ في الأرضِ وقطيعةِ الرحمِ التي توجب اللعنةَ والصممَ والعمى","verses":[{"n":20,"reflection":{"text":"«ويقول الذين آمنوا لولا نزلت سورة فإذا أنزلت سورة محكمة وذكر فيها القتال رأيت الذين في قلوبهم مرض ينظرون إليك نظر المغشي عليه من الموت فأولى لهم»: يقول المؤمنون: هلّا نُزِّلت سورةٌ في القتال، فإذا أُنزِلت سورةٌ محكمةٌ ذُكِر فيها القتالُ رأيت المنافقين ينظرون إليك نظرَ المغشيِّ عليه من الموتِ خوفًا، فويلٌ لهم؛ ففي هذا بيانُ الفرقِ بين شوقِ المؤمنِ للطاعةِ وجزعِ المنافقِ منها؛ فاشتق إلى الطاعةِ ولو شقّت، ولا تجزع من التكاليف، فالمؤمنُ يشتاق للجهاد، والمنافقُ يجزع منه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشوقُ إلى الطاعةِ ولو شقّت، وتركُ الجزعِ من التكاليف."},"action":{"text":"تأمّل الفرقَ بين المؤمنِ والمنافقِ في التكاليف: ويقول الذين آمنوا حرصًا على الجهادِ والطاعة: هلّا، أي فهلّا، نُزِّلت سورةٌ فيها الأمرُ بالقتال؛ فإذا أُنزِلت سورةٌ محكمةٌ واضحةٌ وذُكِر فيها القتالُ، رأيت الذين في قلوبهم مرضٌ من النفاقِ والشكّ ينظرون إليك، يا محمدُ، نظرَ من أُغمِي عليه من سكراتِ الموتِ خوفًا وجبنًا من القتال؛ فأولى لهم، أي فويلٌ وهلاكٌ لهم «ويقول الذين آمنوا لولا نزلت سورة... نظر المغشي عليه من الموت فأولى لهم»؛ ففي هذا بيانُ الفرقِ بين المؤمنِ الذي يشتاق إلى الجهادِ ويتمنّاه، والمنافقِ الذي يجزع منه ويخافه أشدَّ الخوف؛ فالمؤمنُ يطلب الطاعةَ والجهاد، والمنافقُ يفرّ منهما؛ فاشتق أنت إلى الطاعةِ والعملِ الصالحِ ولو شقّ على النفس؛ ولا تجزع من التكاليفِ الشرعيةِ وإن ثقلت؛ فالمؤمنون يشتاقون إلى ما يقرّبهم إلى الله؛ إنما المؤمنون الذين آمنوا بالله ورسوله ثم لم يرتابوا وجاهدوا بأموالهم وأنفسهم؛ فمن اشتاق إلى الطاعةِ فهو المؤمن، ومن جزع منها فهو المريضُ القلب؛ فاجعل شوقك إلى الطاعةِ والجهادِ علامةَ صدقِ إيمانك."}},{"n":21,"reflection":{"text":"«طاعة وقول معروف فإذا عزم الأمر فلو صدقوا الله لكان خيرا لهم»: الأولى بهم طاعةٌ وقولٌ معروف، فإذا جدَّ الأمرُ وجب القتال، فلو صدقوا الله في الإيمانِ والطاعةِ لكان خيرًا لهم؛ ففي هذا الحثُّ على الطاعةِ والصدقِ مع الله؛ فأطع الله واصدق معه في العهدِ والعمل، فالصدقُ مع الله خيرٌ للعبد، فاجعل طاعتك وصدقك مع الله دأبك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطاعةُ والصدقُ مع الله في العهدِ والعمل."},"action":{"text":"تأمّل الحثَّ على الطاعةِ والصدق: الأولى والأليقُ بهؤلاء طاعةٌ لله ورسوله، وقولٌ معروفٌ حسن؛ فإذا عزم الأمرُ وجدَّ ووجب القتالُ فكرهوه؛ فلو صدقوا الله في إيمانهم وطاعتهم وعزمهم لكان خيرًا لهم من النفاقِ والتخلّف «طاعة وقول معروف فإذا عزم الأمر فلو صدقوا الله لكان خيرا لهم»؛ ففي هذا الحثُّ على الطاعةِ والقولِ المعروف، وبيانُ أنّ الصدقَ مع الله خيرٌ للعبد؛ فالطاعةُ والصدقُ خيرٌ من النفاقِ والمخالفة؛ فأطع أنت الله ورسوله في المنشطِ والمكره؛ واصدق مع الله في إيمانك وعهدك وعملك؛ من المؤمنين رجالٌ صدقوا ما عاهدوا الله عليه؛ فالصدقُ مع الله في العزائمِ والأعمالِ خيرٌ للعبدِ في الدنيا والآخرة؛ ليجزيَ الله الصادقين بصدقهم؛ فمن صدق مع الله نفعه صدقه، ومن نافق ضرّه نفاقه؛ فاجعل الطاعةَ والصدقَ مع الله دأبك؛ فبالصدقِ مع الله في العهدِ والعملِ تنال الخيرَ والفلاح؛ فالصدقُ منجاةٌ، والنفاقُ مهلكة."}},{"n":22,"reflection":{"text":"«فهل عسيتم إن توليتم أن تفسدوا في الأرض وتقطعوا أرحامكم»: فهل يُتوقَّع منكم إن تولّيتم عن الطاعةِ وأعرضتم أن تفسدوا في الأرضِ وتقطعوا أرحامكم؟ ففي هذا التحذيرُ من الإفسادِ وقطيعةِ الرحم؛ فاحذر الإفسادَ في الأرضِ وقطعَ الرحم، فأصلح في الأرضِ وصِل رحمك، فالإعراضُ عن الطاعةِ يجرّ إلى الفسادِ والقطيعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإصلاحُ في الأرضِ وصلةُ الرحم، والحذرُ من الإفسادِ والقطيعة."},"action":{"text":"تأمّل التحذيرَ من الإفسادِ والقطيعة: فهل عسيتم وتوقّعتم، أيها المعرضون، إن تولّيتم عن طاعةِ الله وأعرضتم عن دينه، أو إن وُلّيتم أمرَ الناس، أن تفسدوا في الأرضِ بالمعاصي وسفكِ الدماء، وتقطعوا أرحامكم فلا تصلوها؟ «فهل عسيتم إن توليتم أن تفسدوا في الأرض وتقطعوا أرحامكم»؛ ففي هذا التحذيرُ من الإفسادِ في الأرضِ وقطيعةِ الرحم، وأنهما من ثمراتِ الإعراضِ عن الطاعة؛ فالتولّي عن الحقِّ يجرّ إلى الفسادِ والقطيعة؛ فاحذر أنت الإفسادَ في الأرضِ بالمعاصي والظلمِ وسفكِ الدماء؛ واحذر قطيعةَ الرحمِ وهجرَ الأقارب؛ فأصلح في الأرضِ ولا تفسد فيها؛ ولا تفسدوا في الأرضِ بعد إصلاحها؛ وصِل رحمك وأحسن إلى أقاربك؛ واتّقوا الله الذي تساءلون به والأرحام؛ من كان يؤمن بالله واليومِ الآخرِ فليصل رحمه؛ لا يدخل الجنّةَ قاطع؛ فالإعراضُ عن الطاعةِ يجرّ إلى الإفسادِ والقطيعة، والطاعةُ تثمر الإصلاحَ والصلة؛ فمن أصلح ووصل رحمه بورك له، ومن أفسد وقطع لُعِن؛ فاجعل الإصلاحَ في الأرضِ وصلةَ الرحمِ من أعمالك."}},{"n":23,"reflection":{"text":"«أولئك الذين لعنهم الله فأصمهم وأعمى أبصارهم»: أولئك المفسدون القاطعون لعنهم الله فأصمّهم عن سماعِ الحقِّ وأعمى أبصارهم عن رؤيته؛ ففي هذا بيانُ عقوبةِ المفسدين بالصممِ والعمى عن الحق؛ فاحذر أسبابَ اللعنةِ من الإفسادِ والقطيعة، فاستعمل سمعك وبصرك في الحق، فالإعراضُ عن الحقِّ يورث الصممَ والعمى عنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعمالُ السمعِ والبصرِ في الحق، والحذرُ من أسبابِ اللعنة."},"action":{"text":"تأمّل عقوبةَ المفسدين: أولئك المفسدون في الأرضِ القاطعون لأرحامهم هم الذين لعنهم الله وأبعدهم عن رحمته؛ فأصمّهم عن سماعِ الحقِّ سماعَ قبولٍ وانتفاع، وأعمى أبصارهم عن رؤيةِ الحقِّ والاهتداءِ به «أولئك الذين لعنهم الله فأصمهم وأعمى أبصارهم»؛ ففي هذا بيانُ أنّ عقوبةَ المفسدين القاطعين اللعنةُ والصممُ والعمى عن الحق؛ فبإعراضهم عن الحقِّ عاقبهم الله بأن أصمّهم وأعماهم عنه؛ فاحذر أنت أسبابَ اللعنةِ والطردِ من رحمةِ الله: من الإفسادِ في الأرضِ وقطيعةِ الرحمِ والإعراضِ عن الحق؛ واستعمل سمعك في سماعِ الحقِّ والقرآنِ سماعَ قبولٍ وانتفاع؛ وبصرك في النظرِ في آياتِ الله والاهتداءِ بها؛ فلهم قلوبٌ لا يفقهون بها ولهم أعينٌ لا يبصرون بها ولهم آذانٌ لا يسمعون بها؛ فالإعراضُ عن الحقِّ يورث الصممَ والعمى القلبيَّ عنه؛ فمن استعمل سمعه وبصره في الحقِّ نفعاه، ومن أعرض أُصِمَّ وأُعمِي عنه؛ فاجعل سمعك وبصرك في خدمةِ الحقِّ واتّباعه؛ فبذلك تنجو من الصممِ والعمى القلبيّ."}}]},{"title":"تدبّرُ القرآن، والمرتدّون وتسويلُ الشيطان","range":[24,28],"theme":"الحثُّ على تدبّرِ القرآنِ وذمُّ القلوبِ المقفلة، وبيانُ أنّ المرتدّين زيّن لهم الشيطانُ وأملى لهم لمواطأتهم أعداءَ الدينِ سرًّا، وشدّةِ حالهم عند توفّي الملائكةِ لهم لأنهم اتّبعوا ما أسخط الله وكرهوا رضوانه فأحبط أعمالهم","verses":[{"n":24,"reflection":{"text":"«أفلا يتدبرون القرآن أم على قلوب أقفالها»: أفلا يتدبّر هؤلاء القرآنَ ليفهموه ويعملوا به، أم على قلوبهم أقفالٌ تمنع وصولَ الحقِّ إليها؟ ففي هذا الحثُّ على تدبّرِ القرآنِ وذمُّ القلوبِ المقفلة؛ فتدبّر القرآنَ بقلبٍ مفتوحٍ للحق، فالتدبّرُ مفتاحُ الهدى، فاجعل تدبّرَ القرآنِ دأبك، ولا تجعل على قلبك قفلًا يمنعه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تدبّرُ القرآنِ بقلبٍ مفتوحٍ للحق، والحذرُ من إقفالِ القلب."},"action":{"text":"تأمّل الحثَّ على تدبّرِ القرآن: أفلا يتدبّر هؤلاء المعرضون القرآنَ ويتفكّرون في معانيه، ليفهموا ما فيه من الحقِّ والهدى فيعملوا به؟ أم على قلوبهم أقفالٌ مطبقةٌ تمنع وصولَ الحقِّ والهدى إليها، فلا يفقهون ولا ينتفعون؟ «أفلا يتدبرون القرآن أم على قلوب أقفالها»؛ ففي هذا الحثُّ العظيمُ على تدبّرِ القرآن، وذمُّ من أعرض عنه فأُقفِل قلبه؛ فالتدبّرُ هو المقصودُ من إنزالِ القرآن؛ فمن تدبّره اهتدى، ومن أعرض عنه أُقفِل قلبه؛ فتدبّر أنت القرآنَ بقلبٍ حاضرٍ مفتوحٍ للحق؛ كتابٌ أنزلناه إليك مباركٌ ليدّبّروا آياته وليتذكّر أولو الألباب؛ أفلم يدّبّروا القولَ؛ فالتدبّرُ مفتاحُ الهدى والانتفاعِ بالقرآن؛ ولا تجعل على قلبك قفلًا من الكبرِ أو الهوى أو الإعراضِ يمنع الحقَّ من الوصولِ إليه؛ فمن تدبّر القرآنَ بقلبٍ مفتوحٍ اهتدى وانتفع، ومن أعرض عنه بقلبٍ مقفلٍ ضلّ؛ فاجعل تدبّرَ القرآنِ دأبك وعادتك؛ فبتدبّرِ القرآنِ بقلبٍ مفتوحٍ للحقِّ تُنال الهدايةُ والنور."}},{"n":25,"reflection":{"text":"«إن الذين ارتدوا على أدبارهم من بعد ما تبين لهم الهدى الشيطان سول لهم وأملى لهم»: إنّ الذين رجعوا عن الإيمانِ بعد أن تبيّن لهم الهدى، الشيطانُ زيّن لهم وأمهلهم في الأمل؛ ففي هذا بيانُ خطرِ الردّةِ ودورِ الشيطانِ فيها؛ فاحذر الرجوعَ عن الحقِّ بعد معرفته، واحذر تزيينَ الشيطانِ وتسويفَه، فالردّةُ بعد الهدى من تسويلِ الشيطان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ بعد معرفته، والحذرُ من تزيينِ الشيطانِ وتسويفه."},"action":{"text":"تأمّل خطرَ الردّةِ ودورَ الشيطان: إنّ الذين ارتدّوا ورجعوا على أدبارهم إلى الكفرِ والنفاقِ بعد ما تبيّن لهم الهدى وعرفوا الحقَّ بالأدلّة؛ الشيطانُ سوّل لهم وزيّن لهم الكفرَ والباطل، وأملى لهم ومدَّ لهم في الأملِ والأمانيِّ الكاذبة «إن الذين ارتدوا على أدبارهم من بعد ما تبين لهم الهدى الشيطان سول لهم وأملى لهم»؛ ففي هذا بيانُ خطرِ الردّةِ والرجوعِ عن الحقِّ بعد معرفته، وأنّ سببه تسويلُ الشيطانِ وتزيينه وإملاؤه؛ فرجعوا عن الحقِّ بعد وضوحه بتزيينِ الشيطان؛ فاحذر أنت الرجوعَ عن الحقِّ والدينِ بعد ما تبيّن لك؛ فالردّةُ بعد الهدى من أعظمِ الخسران؛ ومن يرتدد منكم عن دينه فيمت وهو كافرٌ فأولئك حبطت أعمالهم؛ واحذر تزيينَ الشيطانِ للباطل، وتسويفه، وإملاءه في الأملِ الكاذب؛ فالشيطانُ يزيّن الباطلَ ويمنّي بالأماني؛ يعدهم ويمنّيهم وما يعدهم الشيطانُ إلا غرورًا؛ فمن ثبت على الحقِّ بعد معرفته نجا، ومن رجع عنه بتزيينِ الشيطانِ خسر؛ فاجعل ثباتك على الحقِّ بعد معرفته، وحذرك من تزيينِ الشيطانِ وتسويفه."}},{"n":26,"reflection":{"text":"«ذلك بأنهم قالوا للذين كرهوا ما نزل الله سنطيعكم في بعض الأمر والله يعلم إسرارهم»: ذلك التسويلُ لأنهم قالوا سرًّا لأعداءِ الدين: سنطيعكم في بعضِ الأمر، والله يعلم أسرارهم؛ ففي هذا كشفُ سرِّ المنافقين وموالاتهم لأعداءِ الدين؛ فاحذر مظاهرةَ أعداءِ الدينِ ولو في بعضِ الأمر، واعلم أنّ الله يعلم أسرارك، فراقبه في سرّك، فموالاةُ أعداءِ الدينِ نفاق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله في السرّ، والحذرُ من موالاةِ أعداءِ الدين."},"action":{"text":"تأمّل كشفَ سرِّ المنافقين: ذلك التسويلُ والإملاءُ لهم، سببه أنهم قالوا سرًّا للذين كرهوا ما نزّل الله من اليهودِ وأعداءِ الدين: سنطيعكم ونوافقكم في بعضِ الأمر، ونعينكم على النبيِّ والمؤمنين؛ والله يعلم إسرارهم وما يخفونه من هذه المواطأةِ والموالاة «ذلك بأنهم قالوا للذين كرهوا ما نزل الله سنطيعكم في بعض الأمر والله يعلم إسرارهم»؛ ففي هذا كشفُ سرِّ المنافقين وموالاتهم لأعداءِ الدينِ في الباطن، وأنّ الله مطّلعٌ على أسرارهم؛ فوالَوا أعداءَ الدينِ سرًّا وواطؤوهم؛ فاحذر أنت مظاهرةَ أعداءِ الدينِ وموالاتهم ولو في بعضِ الأمر؛ ومن يتولّهم منكم فإنه منهم؛ لا تتّخذوا اليهودَ والنصارى أولياء؛ واعلم أنّ الله يعلم أسرارك وما تخفيه؛ يعلم السرَّ وأخفى؛ أم يحسبون أنّا لا نسمع سرّهم ونجواهم بلى؛ فراقب الله في سرّك كما تراقبه في علنك؛ فمن راقب الله في سرّه وترك موالاةَ أعداءِ الدينِ صدق إيمانه، ومن والاهم سرًّا نافق؛ فاجعل مراقبةَ الله في سرّك، وبراءتك من أعداءِ الدين، علامةَ صدقك."}},{"n":27,"reflection":{"text":"«فكيف إذا توفتهم الملائكة يضربون وجوههم وأدبارهم»: فكيف يكون حالهم إذا قبضت الملائكةُ أرواحهم ضاربين وجوههم وأدبارهم؟ ففي هذا بيانُ شدّةِ حالِ المنافقين عند الموت؛ فاحذر أن يكون هذا حالك عند الموت، فأصلح باطنك وظاهرك، فمن ساء عمله ساء حالُه عند الموت.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إصلاحُ الباطنِ والظاهر، والاستعدادُ لحُسنِ الخاتمة."},"action":{"text":"تأمّل شدّةَ حالِ المنافقين عند الموت: فكيف يكون حالُ هؤلاء المنافقين وشدّتهم إذا توفّتهم الملائكةُ وقبضت أرواحهم، حالَ كونهم يضربون وجوههم وأدبارهم عقوبةً لهم على نفاقهم وموالاتهم لأعداءِ الدين؟ «فكيف إذا توفتهم الملائكة يضربون وجوههم وأدبارهم»؛ ففي هذا بيانُ شدّةِ حالِ المنافقين عند الموت، وأنّ الملائكةَ تضرب وجوههم وأدبارهم عند قبضِ أرواحهم؛ فسوءُ الباطنِ يظهر أثره عند الموت؛ ولو ترى إذ يتوفّى الذين كفروا الملائكةُ يضربون وجوههم وأدبارهم؛ فاحذر أنت أن يكون هذا حالك عند الموت من سوءِ الخاتمة؛ فأصلح باطنك كما تصلح ظاهرك؛ واحذر النفاقَ وموالاةَ أعداءِ الدين؛ فمن ساء عمله وباطنه ساء حاله عند الموت، ومن صلح باطنه وظاهره حسنت خاتمته؛ الأعمالُ بالخواتيم؛ فاعمل لحُسنِ الخاتمةِ بإصلاحِ الباطنِ والظاهرِ والإخلاصِ والاستقامة؛ فاجعل همّك إصلاحَ باطنك وظاهرك؛ فبصلاحِ الباطنِ والظاهرِ تُرجى حُسنُ الخاتمة."}},{"n":28,"reflection":{"text":"«ذلك بأنهم اتبعوا ما أسخط الله وكرهوا رضوانه فأحبط أعمالهم»: ذلك العذابُ لأنهم اتّبعوا ما يُسخِط الله وكرهوا ما يُرضيه، فأحبط أعمالهم؛ ففي هذا بيانُ سببِ حبوطِ أعمالِ المنافقين؛ فاتّبع ما يُرضي الله واترك ما يُسخِطه، فاتّباعُ ما يُسخِط الله يحبط العمل، فاجعل رضا الله غايتك واجتنب سخطه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ ما يُرضي الله واجتنابُ ما يُسخِطه، لسلامةِ العمل."},"action":{"text":"تأمّل سببَ حبوطِ أعمالِ المنافقين: ذلك العذابُ عند الموتِ وبعده، سببه أنهم اتّبعوا ما أسخط الله من الكفرِ والنفاقِ وموالاةِ أعدائه؛ وكرهوا رضوانه وما يُرضيه من الإيمانِ والطاعة؛ فأحبط الله أعمالهم وأبطلها فلا تنفعهم «ذلك بأنهم اتبعوا ما أسخط الله وكرهوا رضوانه فأحبط أعمالهم»؛ ففي هذا بيانُ أنّ سببَ حبوطِ أعمالِ المنافقين اتّباعُهم ما يُسخِط الله وكراهتُهم رضوانه؛ فاتّبعوا مساخطَ الله وكرهوا مراضيه فحبطت أعمالهم؛ فاتّبع أنت ما يُرضي الله من الإيمانِ والطاعةِ والإخلاص؛ واترك ما يُسخِطه من الكفرِ والمعاصي والنفاق؛ واجعل رضا الله غايتك في كلِّ عمل؛ ورضوانٌ من الله أكبر؛ يبتغون فضلًا من الله ورضوانًا؛ فاتّباعُ ما يُسخِط الله يحبط العمل ويورث العذاب؛ فمن اتّبع رضوانَ الله سعد ونجا، ومن اتّبع مساخطه حبط عمله وعُذّب؛ فاجعل رضا الله غايتك، واجتناب سخطه دأبك؛ فباتّباعِ ما يُرضي الله واجتنابِ ما يُسخِطه يسلم عملك وينجو من الحبوط."}}]},{"title":"كشفُ أضغانِ المنافقين، والابتلاءُ لتمييزِ الصادقين","range":[29,32],"theme":"أنّ الله سيُخرِج أضغانَ مرضى القلوبِ ويُعرَفون بسيماهم ولحنِ قولهم، وأنه يبتليهم حتى يتبيّن المجاهدون والصابرون، وأنّ الذين كفروا وصدّوا وشاقّوا الرسولَ لن يضرّوا الله شيئًا وسيُحبِط أعمالهم","verses":[{"n":29,"reflection":{"text":"«أم حسب الذين في قلوبهم مرض أن لن يخرج الله أضغانهم»: أظنّ المنافقون الذين في قلوبهم مرضٌ أنّ الله لن يُظهِر أحقادهم وما يكتمون؟ ففي هذا بيانُ أنّ الله يكشف ما في القلوب؛ فاحذر أن تُبطِن حقدًا أو نفاقًا فالله مُظهِره، فطهّر قلبك من الأضغان، فما في القلوبِ لا يخفى على الله وسيُكشَف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تطهيرُ القلبِ من الأضغان، وإدراكُ أنّ الله يكشف ما فيه."},"action":{"text":"تأمّل بيانَ أنّ الله يكشف ما في القلوب: أم ظنّ المنافقون الذين في قلوبهم مرضٌ من الشكِّ والنفاقِ أنّ الله لن يُخرِج ويُظهِر أضغانهم، أي أحقادهم وما يكتمونه من بغضِ الإسلامِ والمؤمنين؟ بلى سيُظهِرها الله ويفضحهم بها «أم حسب الذين في قلوبهم مرض أن لن يخرج الله أضغانهم»؛ ففي هذا بيانُ أنّ الله سيكشف ما في قلوبِ المنافقين من الأحقاد، وأنه لا يخفى عليه شيء؛ فظنّوا أنّ ما في قلوبهم يخفى، فأخبر أنه سيُظهِره؛ فاحذر أنت أن تُبطِن حقدًا أو نفاقًا أو غشًّا للمسلمين، فإنّ الله مُظهِره وكاشفه؛ فطهّر قلبك من الأضغانِ والأحقادِ والغلِّ على المسلمين؛ ونزعنا ما في صدورهم من غلٍّ إخوانًا؛ الذين يقولون ربنا اغفر لنا ولإخواننا الذين سبقونا بالإيمانِ ولا تجعل في قلوبنا غلًّا للذين آمنوا؛ فما في القلوبِ من خيرٍ أو شرٍّ لا يخفى على الله وسيُكشَف يومَ القيامة؛ يومَ تُبلى السرائر؛ فمن طهّر قلبه من الأضغانِ سلم، ومن أبطنها فُضِح؛ فاجعل تطهيرَ قلبك من الأحقادِ والغلِّ همّك؛ فبسلامةِ القلبِ تنجو، وبأضغانه تُفضَح."}},{"n":30,"reflection":{"text":"«ولو نشاء لأريناكهم فلعرفتهم بسيماهم ولتعرفنهم في لحن القول والله يعلم أعمالكم»، ولو نشاء لأريناك المنافقين فعرفتهم بعلاماتهم، ولتعرفنّهم في فحوى كلامهم، والله يعلم أعمالكم؛ ففي هذا بيانُ أنّ المنافقَ يُعرَف بلحنِ قوله؛ فتفطّن لعلاماتِ النفاقِ في القولِ والفعل، واعلم أنّ الله يعلم أعمالك، فراقب الله واحذر أن تظهر عليك علاماتُ النفاق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفطّنُ لعلاماتِ النفاق، ومراقبةُ الله في الأعمال."},"action":{"text":"تأمّل بيانَ أنّ المنافقَ يُعرَف بكلامه: ولو نشاء، يا محمدُ، لأريناك المنافقين بأعيانهم فعرفتهم بعلاماتهم وسيماهم الظاهرةِ عليهم؛ ولتعرفنّهم قطعًا في لحنِ القولِ وفحواه ومعناه، فإنّ ما في القلبِ يظهر في اللسان؛ والله يعلم أعمالكم جميعًا فيجازيكم عليها «ولو نشاء لأريناكهم فلعرفتهم بسيماهم ولتعرفنهم في لحن القول والله يعلم أعمالكم»؛ ففي هذا بيانُ أنّ المنافقَ لا بدّ أن تظهر عليه علاماتُ نفاقه في فحوى كلامه، وأنّ الله يعلم الأعمالَ كلَّها؛ فما يُبطِنه المنافقُ يظهر في لحنِ قوله؛ فتفطّن أنت لعلاماتِ النفاقِ في القولِ والفعل، لتحذرها في نفسك وتعرفها في غيرك؛ فإنّ اللسانَ ترجمانُ القلب؛ ما أسرَّ أحدٌ سريرةً إلا أظهرها الله على صفحاتِ وجهه وفلتاتِ لسانه؛ واعلم أنّ الله يعلم أعمالك كلَّها ظاهرها وباطنها فراقبه؛ فمن راقب الله وطهّر قلبه سلم لسانه وعمله، ومن نافق ظهر نفاقه في قوله؛ فاجعل مراقبةَ الله والتفطّنَ لعلاماتِ النفاقِ سبيلَ سلامتك؛ فبمراقبةِ الله وصدقِ الباطنِ يسلم القولُ والعمل."}},{"n":31,"reflection":{"text":"«ولنبلونكم حتى نعلم المجاهدين منكم والصابرين ونبلو أخباركم»، ولنختبرنّكم حتى يظهر المجاهدون والصابرون منكم، ونختبر أخباركم؛ ففي هذا بيانُ حكمةِ الابتلاءِ في تمييزِ الصادقين؛ فاصبر واثبت في الابتلاءِ لتكون من المجاهدين الصابرين، فالابتلاءُ يميّز الصادقَ من المنافق، فاجعل صبرك وجهادك في الابتلاءِ برهانَ صدقك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ والثباتُ في الابتلاء، لتكون من الصادقين المجاهدين."},"action":{"text":"تأمّل حكمةَ الابتلاء: ولنبلونّكم، أيها المؤمنون، ونختبرنّكم بالجهادِ والتكاليفِ والشدائد، حتى نعلم علمًا يظهر للناسِ ويتعلّق به الجزاءُ: المجاهدين منكم في سبيلِ الله، والصابرين على الطاعةِ والبلاء؛ ونبلوَ ونختبر أخباركم وأحوالكم، ليتبيّن الصادقُ من الكاذب «ولنبلونكم حتى نعلم المجاهدين منكم والصابرين ونبلو أخباركم»؛ ففي هذا بيانُ أنّ الله يبتلي عباده ليميّز المجاهدَ الصابرَ الصادقَ من المنافقِ المتخلّف؛ فالابتلاءُ محكُّ الصدق؛ فاصبر أنت واثبت في الابتلاءِ والتكاليفِ والشدائد؛ لتكون من المجاهدين الصابرين الصادقين؛ أحسب الناسُ أن يُتركوا أن يقولوا آمنّا وهم لا يُفتَنون؛ ولنبلونّكم بشيءٍ من الخوفِ والجوع... وبشّر الصابرين؛ فالابتلاءُ يميّز الصادقَ من المنافق، والمجاهدَ من القاعد؛ فمن صبر وجاهد ظهر صدقه، ومن جزع وتخلّف ظهر نفاقه؛ فاجعل صبرك وثباتك وجهادك في الابتلاءِ برهانَ صدقِ إيمانك؛ فبالصبرِ والجهادِ في الابتلاءِ تكون من الصادقين."}},{"n":32,"reflection":{"text":"«إن الذين كفروا وصدوا عن سبيل الله وشاقوا الرسول من بعد ما تبين لهم الهدى لن يضروا الله شيئا وسيحبط أعمالهم»: إنّ الذين كفروا وصدّوا عن سبيلِ الله وعادوا الرسولَ بعد ما تبيّن لهم الهدى، لن يضرّوا الله شيئًا، وسيُحبِط أعمالهم؛ ففي هذا بيانُ أنّ الكافرين المعاندين لا يضرّون إلا أنفسهم؛ فاحذر الكفرَ والصدَّ ومشاقّةَ الرسول، فإنها لا تضرّ إلا صاحبها، فالزم طاعةَ الرسولِ ونصرةَ دينه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طاعةُ الرسولِ ونصرةُ دينه، وإدراكُ أنّ المعاندَ لا يضرّ إلا نفسه."},"action":{"text":"تأمّل بيانَ أنّ المعاندين لا يضرّون إلا أنفسهم: إنّ الذين كفروا بالله ورسوله، وصدّوا الناسَ عن سبيلِ الله ودينه، وشاقّوا الرسولَ وعادوه وخالفوه من بعد ما تبيّن لهم الهدى وعرفوا الحقّ؛ لن يضرّوا الله شيئًا بكفرهم وصدّهم ومشاقّتهم؛ وسيُحبِط الله أعمالهم فلا تنفعهم «إن الذين كفروا وصدوا عن سبيل الله وشاقوا الرسول من بعد ما تبين لهم الهدى لن يضروا الله شيئا وسيحبط أعمالهم»؛ ففي هذا بيانُ أنّ الكافرين الصادّين المشاقّين للرسولِ لا يضرّون الله، وإنما يضرّون أنفسهم بحبوطِ أعمالهم؛ فكفرهم وعنادهم يعود عليهم؛ فاحذر أنت الكفرَ والصدَّ عن سبيلِ الله ومشاقّةَ الرسول؛ فإنها لا تضرّ الله شيئًا، وإنما تضرّ صاحبها بحبوطِ عمله؛ ومن يشاقق الرسولَ من بعد ما تبيّن له الهدى ويتّبع غيرَ سبيلِ المؤمنين نولّه ما تولّى ونصله جهنّم؛ فالزم أنت طاعةَ الرسولِ واتّباعه ونصرةَ دينه؛ فمن أطاع الرسولَ ونصر دينه فاز، ومن عانده وشاقّه خسر وحبط عمله؛ فاجعل طاعتك للرسولِ ونصرتك لدينه سبيلَ فوزك."}}]},{"title":"طاعةُ الله والرسول، والنهيُ عن الوهن، وحقيقةُ الدنيا والإنفاق","range":[33,38],"theme":"الأمرُ بطاعةِ الله والرسولِ وعدمِ إبطالِ الأعمال، وأنّ من مات كافرًا لن يُغفَر له، والنهيُ عن الوهنِ ودعوةِ السلمِ ذلًّا فالمؤمنون الأعلون والله معهم، وأنّ الحياةَ الدنيا لعبٌ ولهو، والحثُّ على الإنفاقِ في سبيلِ الله وذمُّ البخلِ فالله الغنيُّ والعبادُ الفقراء","verses":[{"n":33,"reflection":{"text":"«يا أيها الذين آمنوا أطيعوا الله وأطيعوا الرسول ولا تبطلوا أعمالكم»: يا أيها المؤمنون أطيعوا الله وأطيعوا الرسول، ولا تبطلوا أعمالكم بالكفرِ والنفاقِ والمعاصيِ والرياء؛ ففي هذا الأمرُ بالطاعةِ والنهيُ عن إبطالِ العمل؛ فأطع الله ورسوله، واحفظ عملك من كلِّ ما يبطله، فالطاعةُ سبيلُ الفلاح، وإبطالُ العملِ خسران، فاحفظ أعمالك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طاعةُ الله والرسول، وحفظُ العملِ من كلِّ ما يبطله."},"action":{"text":"تأمّل الأمرَ بالطاعةِ وحفظِ العمل: يا أيها الذين آمنوا، أطيعوا الله في فرائضه وأوامره، وأطيعوا الرسولَ فيما جاء به من الشرع؛ ولا تبطلوا أعمالكم وتحبطوها بالكفرِ والنفاقِ والرياءِ والمنِّ والمعاصيِ ومخالفةِ الرسول «يا أيها الذين آمنوا أطيعوا الله وأطيعوا الرسول ولا تبطلوا أعمالكم»؛ ففي هذا الأمرُ بطاعةِ الله والرسول، والنهيُ عن إبطالِ الأعمالِ بما يحبطها؛ فالطاعةُ تُثبِت العمل، والمعصيةُ والرياءُ تُبطِله؛ فأطع أنت الله ورسوله في كلِّ ما أمرا؛ واحفظ عملك من كلِّ ما يبطله ويحبطه؛ من الرياءِ والعُجبِ والمنِّ والأذى والمعاصي والردّة؛ لا تبطلوا صدقاتكم بالمنِّ والأذى؛ ومن يكفر بالإيمانِ فقد حبط عمله؛ فالطاعةُ سبيلُ الفلاح، وإبطالُ العملِ خسرانٌ عظيم؛ فمن أطاع وحفظ عمله فاز، ومن عصى أو أبطل عمله خسر؛ فاجعل طاعةَ الله والرسولِ دأبك، وحفظَ عملك من المبطلاتِ همّك؛ فبالطاعةِ وحفظِ العملِ تنال الفلاح."}},{"n":34,"reflection":{"text":"«إن الذين كفروا وصدوا عن سبيل الله ثم ماتوا وهم كفار فلن يغفر الله لهم»: إنّ الذين كفروا وصدّوا عن سبيلِ الله ثم ماتوا على الكفرِ فلن يغفر الله لهم؛ ففي هذا بيانُ أنّ الموتَ على الكفرِ يمنع المغفرة؛ فاحذر أن تموت على كفرٍ أو معصيةٍ مصرًّا، فبادر بالتوبةِ قبل الموت، فمن مات كافرًا فلا مغفرةَ له، فتب قبل فواتِ الأوان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالتوبةِ قبل الموت، والحذرُ من الموتِ على الكفر."},"action":{"text":"تأمّل أنّ الموتَ على الكفرِ يمنع المغفرة: إنّ الذين كفروا بالله ورسوله، وصدّوا الناسَ عن سبيلِ الله ودينه، ثم ماتوا وهم كفّارٌ مصرّون على كفرهم لم يتوبوا؛ فلن يغفر الله لهم أبدًا، بل يخلّدهم في النار «إن الذين كفروا وصدوا عن سبيل الله ثم ماتوا وهم كفار فلن يغفر الله لهم»؛ ففي هذا بيانُ أنّ من مات على الكفرِ فلا مغفرةَ له، وأنّ الإصرارَ حتى الموتِ يقطع الرجاء؛ فالتوبةُ تُقبَل ما لم يمت العبدُ أو تطلع الشمسُ من مغربها؛ فاحذر أنت أن تموت على كفرٍ أو نفاقٍ أو معصيةٍ مصرًّا عليها؛ فبادر بالتوبةِ الصادقةِ قبل أن يفاجئك الموت؛ إنّ الله لا يغفر أن يُشرَك به ويغفر ما دون ذلك لمن يشاء؛ إنما التوبةُ على الله للذين يعملون السوءَ بجهالةٍ ثم يتوبون من قريب؛ فمن تاب قبل الموتِ غُفِر له، ومن مات مصرًّا على الكفرِ لم يُغفَر له؛ فبادر بالتوبةِ والإنابةِ إلى الله قبل فواتِ الأوان؛ فاجعل التوبةَ دأبك، ولا تسوّف بها؛ فبالتوبةِ قبل الموتِ تُنال المغفرة."},"qadiyya":{"title":"قضيّةُ مطلقٍ في الحبوط رُدَّ إلى قيده","question":"قال الله: ﴿إِنَّ الَّذِينَ كَفَرُوا وَصَدُّوا عَنْ سَبِيلِ اللَّهِ ثُمَّ مَاتُوا وَهُمْ كُفَّارٌ فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ﴾.\nوقد جاء الحبوطُ في مواضعَ معلّقًا بالكفر وحده، كقوله ﴿وَمَنْ يَكْفُرْ بِالْإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ﴾، وجاء ها هنا **مقرونًا بالموت عليه**.\nفالقضيّة: **ما موقع ﴿ثُمَّ مَاتُوا وَهُمْ كُفَّارٌ﴾ من الحكم؟** أوصفٌ زيد للتصوير، أم قيدٌ يتوقّف عليه؟ ثمّ: **ما مصيرُ النصوص التي أطلقت الحبوط ولم تذكر موتًا؟** ثمّ: **ماذا يبقى لمن أفنى عمرَه في الكفر ثمّ أدركته التوبة؟**","background":"ولا يظهر أثرُ القيد حتى يُفرّق بين نوعين من النصّ:\nفالمطلقُ ما ورد الحكمُ فيه بغير شرطٍ ولا وصف. والمقيّدُ ما زيد فيه ما يحصر الحكم في صورة.\nفإذا اتّحد الحكمُ والسببُ في النصّين، لم يكن بينهما تعارض، **بل يكون المقيّدُ بيانًا للمطلق**، فيُقرأ المطلقُ على وفقه. وها هنا الحكمُ حبوطُ العمل، والسببُ الكفر.\nوثمّ فرقٌ ثانٍ يحتاجه القارئ: **بين انعقاد السبب ونفوذ أثره**. فقد ينعقد السببُ ويبقى الأثرُ موقوفًا حتى يتحقّق شرطُه. وعلى هذا مدارُ المسألة.","what_happened":"**بدأ السعديُّ بالحكم على الآية قبل تفسير ألفاظها**، فضمّ إليها آيةَ البقرة ﴿وَمَنْ يَرْتَدِدْ مِنْكُمْ عَنْ دِينِهِ فَيَمُتْ وَهُوَ كَافِرٌ فَأُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَةِ﴾، ثمّ قال إنّهما «مقيدتان، لكل نص مطلق، فيه إحباط العمل بالكفر، فإنه مقيد بالموت عليه».\nثمّ فسّر ﴿إِنَّ الَّذِينَ كَفَرُوا﴾: «بالله وملائكته وكتبه ورسله واليوم الآخر».\nثمّ فسّر الصدّ، فجعل المصدود «الخلق»، وبيّن وجهه: «بتزهيدهم إياهم بالحق، ودعوتهم إلى الباطل، وتزيينه».\n⭐ **ثمّ فسّر القيد نفسه** ﴿ثُمَّ مَاتُوا وَهُمْ كُفَّارٌ﴾ بقوله: «لم يتوبوا منه».\nثمّ فسّر ﴿فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ﴾: «لا بشفاعة ولا بغيرها»، وساق تعليلَه: «لأنه قد تحتم عليهم العقاب، وفاتهم الثواب، ووجب عليهم الخلود في النار، وسدت عليهم رحمة الرحيم الغفار».\n⭐ **ثمّ انتقل من المنطوق إلى المفهوم**: «ومفهوم الآية الكريمة أنهم إن تابوا من ذلك قبل موتهم، فإن الله يغفر لهم ويرحمهم، ويدخلهم الجنة، ولو كانوا مفنين أعمارهم في الكفر به والصد عن سبيله، والإقدام على معاصيه».\nثمّ ختم بالثناء: «فسبحان من فتح لعباده أبواب الرحمة، ولم يغلقها عن أحد، ما دام حيا متمكنا من التوبة»، ثمّ: «وسبحان الحليم، الذي لا يعاجل العاصين بالعقوبة، بل يعافيهم، ويرزقهم، كأنهم ما عصوه مع قدرته عليهم».","the_verdict":"فالحاصلُ أنّ **الكفر سببُ الحبوط، والموتَ عليه هو الذي يُبرمه**. فالقيدُ عنده حاكمٌ لا مُهمَل؛ صرّح بأنّ النصّ المطلق في إحباط العمل بالكفر «مقيد بالموت عليه». فلم يُسقط المطلق ولم يعارض به المقيّد، بل بقيت النصوص المطلقة على معناها، وإنّما عُيّن وقتُ نفوذها.\nوموضعُ الدقّة أنّه قدّم الجمع بين النصّين على شرح المفردات؛ فبدأ بقوله «مقيدتان» قبل أن يفسّر ﴿إِنَّ الَّذِينَ كَفَرُوا﴾. ولم يذكر لصنيعه علّة، **وظاهرُه عندي أنّ الإشكال كان عنده في نصٍّ يُقرأ مع نصّ لا في لفظٍ يُبيَّن**.\n⭐ وقد تقدّم في هذه السورة ﴿وَسَيُحْبِطُ أَعْمَالَهُمْ﴾، وقال في الأعمال التي يُرجى بها الثواب: «لا تقبل لعدم وجود شرطها»، وظاهرُ الشرط عنده الإيمان. **وإنّما أنزلنا عليه قيدَ الموت من قاعدته المتقدّمة**، وهو تنزيلٌ منّا لا تعيينٌ منه.\n⭐ وممّا يُلحظ أنّه فسّر الموت على الكفر بـ«لم يتوبوا منه»؛ **وظاهرُ هذا عندي أنّ المناط فواتُ التوبة لا امتدادُ الزمن**. فالعمرُ الطويل في الكفر ليس هو الموجب، وإنّما الموجبُ أن يسبق الأجلُ الرجوع. وقد صرّح بذلك في المفهوم: «ولو كانوا مفنين أعمارهم في الكفر». فمن أدركته التوبةُ قبل موته بقيت له المغفرةُ والرحمةُ ودخولُ الجنّة، وهو نصُّ مفهومه، لا تخفيفَ عقوبةٍ فحسب.\n⭐ وأمّا الغلطُ فيقع في جهتين متقابلتين:\nالأولى: أن يؤخذ المطلقُ وحده، **فيُحكم على حيٍّ بأنّ بابَه قد أُغلق**؛ وهذا خلافُ قوله «ما دام حيا متمكنا من التوبة».\nوالثانية: أن يؤخذ المفهومُ وحده، **فيُتّكل على تأخير التوبة**؛ وقد سدّ الإمامُ هذا في المنطوق بقوله «لا بشفاعة ولا بغيرها».","for_you":"فأمّا الذي تخرج به فثلاثة:\n**الأوّل: أبقِ البابَ مفتوحًا لكلّ حيّ.** فإن كان لك قريبٌ أو صاحبٌ قطعتَ الرجاء فيه، فأعِد وصلَه ودعوتَه هذا الأسبوع بفعلٍ يُرى: زيارةٍ أو رسالةٍ أو هديّة. ولا تُنزل عليه حكمَ الخاتمة وهو لم يبلغها.\n**والثاني: عجّل التوبة ولا تجعلها نيّةً مؤجّلة.** عيّن ذنبًا واحدًا بعينه، وأحدِث منه توبةً قبل أن تقوم من مجلسك هذا. فالذي عُلّق عليه الحكم هو الموت، ووقتُه غير معلومٍ لك.\n**والثالث: لا ترْوِ نصوصَ الحبوط على إطلاقها.** فإذا مرّ بك نصٌّ في إحباط العمل بالكفر فقف حتى تنظر في مقيّده، ثمّ اذكر القيدَ معه كلّما رويتَه؛ فإسقاطُ القيد يقلب البيانَ قنوطًا.","grade":"ma'thur","source":"حكمُ السعديّ على الآيتين («مقيدتان، لكل نص مطلق»)، وتفسيرُه الكفرَ («بالله وملائكته») والصدَّ («بتزهيدهم إياهم بالحق»)، وتفسيرُه القيدَ («لم يتوبوا منه»)، ونفيُه المغفرةَ («لا بشفاعة ولا بغيرها») وتعليلُه («لأنه قد تحتم عليهم العقاب»)، واستخراجُه المفهومَ («ومفهوم الآية الكريمة أنهم إن تابوا»)، وثناؤه في آخره («فسبحان من فتح لعباده أبواب الرحمة»): كلُّها بنصّها في تفسير السعديّ (٤٧:٣٤). وقولُه في الأعمال إنّها «لا تقبل لعدم وجود شرطها» في تفسيره (٤٧:٣٢).","honesty":"وممّا يجب أن يُقال:\nتفريقُنا في التمهيد بين المطلق والمقيّد، واشتراطُنا اتّحادَ الحكم والسبب، وتفريقُنا بين انعقاد السبب ونفوذ أثره: **تمهيدٌ منّا** لتقريب صنيعه، وليس نصًّا له، وإن كان مبنيًّا على حكمه بأنّهما «مقيدتان».\nوتعييننا ﴿وَمَنْ يَكْفُرْ بِالْإِيمَانِ﴾ مثالًا للمطلق **تمثيلٌ منّا**؛ فإنّه لم يسمّ نصًّا بعينه، بل أطلق فقال «لكل نص مطلق».\nوعدُّنا ﴿وَسَيُحْبِطُ أَعْمَالَهُمْ﴾ داخلًا فيما يحكمه هذا القيد **تنزيلٌ منّا** لقاعدته على موضعٍ قريب، ولم ينصّ عليه؛ وظاهرُ لفظه في «شرطها» أنّ الشرط الإيمان لا الخاتمة.\nوقولُنا في علّة تقديمه الجمعَ بين النصّين **استظهارٌ منّا**؛ فالترتيبُ ثابتٌ في نصّه، وأمّا سببُه فلم يذكره.\nوقولُنا إنّ المناط فواتُ التوبة لا امتدادُ الزمن **استنباطٌ منّا** من تفسيره الموتَ على الكفر بـ«لم يتوبوا منه»، ومن قوله «ولو كانوا مفنين أعمارهم في الكفر».\nوقسمةُ الغلط إلى جهتين متقابلتين ترتيبٌ منّا على كلامه المجموع، لا تقسيمٌ نصّ عليه.\nوالأمثلةُ في ما تخرج به من عندنا؛ ومن رأى أنّا وسّعنا فليردّه."}},{"n":35,"reflection":{"text":"«فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون والله معكم ولن يتركم أعمالكم»: فلا تضعفوا وتدعوا الكفّارَ إلى الصلحِ ذلًّا وأنتم الأعلون، والله معكم بالنصر، ولن ينقصكم ثوابَ أعمالكم؛ ففي هذا النهيُ عن الوهنِ والدعوةِ للسلمِ ذلًّا، والبشارةُ بالمعيّةِ والأجر؛ فلا تهن في الحقِّ ولا تذلّ لأهلِ الباطل، فأنت الأعلى بالحقِّ والله معك، فاثبت واعلم أنّ الله لن ينقص أجرك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ في الحقِّ وعدمُ الوهن، والثقةُ بمعيّةِ الله وأجره."},"action":{"text":"تأمّل النهيَ عن الوهنِ والبشارةَ بالمعيّة: فلا تهنوا، أيها المؤمنون، ولا تضعفوا عن قتالِ أعدائكم، ولا تدعوا الكفّارَ إلى الصلحِ والمسالمةِ ضعفًا وذلًّا وأنتم الأعلون الغالبون بالحجّةِ والنصر؛ والله معكم بالعونِ والنصرِ والتأييد؛ ولن يتركم ولن ينقصكم شيئًا من ثوابِ أعمالكم، بل يوفّيكم أجورها «فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون والله معكم ولن يتركم أعمالكم»؛ ففي هذا النهيُ عن الوهنِ والضعفِ ودعوةِ العدوِّ إلى السلمِ ذلًّا، والبشارةُ بأنهم الأعلون وأنّ الله معهم ولن ينقص أجرهم؛ فلا تضعفوا أمام أهلِ الباطل؛ فأنت الأعلى بالحقِّ الذي معك؛ فلا تهن أنت في الحقِّ ولا تضعف عنه، ولا تذلّ لأهلِ الباطل؛ ولا تهنوا ولا تحزنوا وأنتم الأعلون إن كنتم مؤمنين؛ فأنت الأعلى ما دمت على الحقِّ والإيمان؛ والله معك بالعونِ والنصرِ والتأييد؛ إنّ الله مع الذين اتّقوا والذين هم محسنون؛ ولن ينقص الله أجرك وثوابَ عملك؛ فمن ثبت في الحقِّ ولم يهن نُصِر، ومن وهن وذلّ لأهلِ الباطلِ خُذِل؛ فاجعل ثباتك في الحقِّ، وثقتك بمعيّةِ الله وأجره؛ فبالثباتِ والثقةِ بالله تُنال العزّةُ والنصر."}},{"n":36,"reflection":{"text":"«إنما الحياة الدنيا لعب ولهو وإن تؤمنوا وتتقوا يؤتكم أجوركم ولا يسألكم أموالكم»: إنما الحياةُ الدنيا لعبٌ ولهوٌ زائل، وإن تؤمنوا وتتّقوا يعطكم أجوركم، ولا يسألكم أموالكم كلَّها؛ ففي هذا بيانُ حقيقةِ الدنيا والحثُّ على الإيمانِ والتقوى؛ فلا تغترّ بالدنيا اللاهية، وآمن واتّق لتنال أجرك، فالدنيا لعبٌ زائل، والباقي الإيمانُ والتقوى، فاعمل للباقي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالدنيا، والإيمانُ والتقوى لنيلِ الأجر."},"action":{"text":"تأمّل حقيقةَ الدنيا والحثَّ على الإيمان: إنما الحياةُ الدنيا لعبٌ تلعب به الأبدان، ولهوٌ تلهو به القلوب، زائلةٌ منقضية، لا تدوم ولا تبقى؛ وإن تؤمنوا بالله ورسوله وتتّقوه بفعلِ أوامره واجتنابِ نواهيه، يؤتكم أجوركم كاملةً على أعمالكم؛ ولا يسألكم أموالكم كلَّها، بل القليلَ منها في الزكاةِ والنفقة «إنما الحياة الدنيا لعب ولهو وإن تؤمنوا وتتقوا يؤتكم أجوركم ولا يسألكم أموالكم»؛ ففي هذا بيانُ حقيقةِ الدنيا أنها لعبٌ ولهوٌ زائل، والحثُّ على الإيمانِ والتقوى لنيلِ الأجر؛ فالدنيا متاعُ الغرور، والباقي عملُ الآخرة؛ فلا تغترّ أنت بالدنيا اللاهيةِ الزائلة؛ وما الحياةُ الدنيا إلا متاعُ الغرور؛ اعلموا أنما الحياةُ الدنيا لعبٌ ولهوٌ وزينة؛ وآمن بالله واتّقه لتنال أجرك الكامل؛ فالإيمانُ والتقوى هما الباقيان النافعان؛ ولا يطلب الله منك أموالك كلَّها، بل يسيرًا منها في الزكاةِ والنفقة لمصلحتك؛ فمن آمن واتّقى نال أجره، ومن اغترّ بالدنيا خسر؛ فاجعل همّك الإيمانَ والتقوى والعملَ للباقي، لا الاغترارَ بالدنيا الزائلة."}},{"n":37,"reflection":{"text":"«إن يسألكموها فيحفكم تبخلوا ويخرج أضغانكم»: إن يسألكم الله أموالكم كلَّها ويلحّ عليكم لبخلتم، ولأظهر ذلك أحقادكم؛ ففي هذا بيانُ رحمةِ الله بعدمِ تكليفِ كلِّ المال، وكشفُ شحِّ النفوس؛ فاحذر شحَّ نفسك، وجاهدها على البذل، فالشحُّ داءٌ يظهر عند الطلب، فطهّر نفسك من الشحِّ بالإنفاق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مجاهدةُ النفسِ على البذل، والتطهّرُ من الشح."},"action":{"text":"تأمّل رحمةَ الله وكشفَ الشح: إن يسألكم الله أموالكم كلَّها ويُلحّ عليكم في طلبها، تبخلوا بها وتمنعوها؛ ويُخرِج ذلك السؤالُ أضغانكم، أي ما في نفوسكم من الشحِّ والكراهيةِ للبذل؛ فلرحمته بكم لم يطلبها كلَّها «إن يسألكموها فيحفكم تبخلوا ويخرج أضغانكم»؛ ففي هذا بيانُ رحمةِ الله بعباده حيث لم يكلّفهم بذلَ كلِّ أموالهم، وكشفُ ما في النفوسِ من الشحِّ الذي يظهر عند الإلحافِ في الطلب؛ فلو طُلِبت الأموالُ كلُّها لبخلت النفوسُ وظهرت أحقادها؛ فاحذر أنت شحَّ نفسك الذي يمنعك من البذلِ في سبيلِ الله؛ وجاهد نفسك على الإنفاقِ والبذل؛ ومن يُوقَ شحَّ نفسه فأولئك هم المفلحون؛ فالشحُّ داءٌ كامنٌ يظهر عند الطلبِ والإلحاف؛ وأُحضِرت الأنفسُ الشحَّ؛ فطهّر نفسك من الشحِّ والبخلِ بالإنفاقِ والبذلِ في سبيلِ الله؛ فمن جاهد نفسه على البذلِ أفلح، ومن أطاع شحّه خسر؛ فاجعل مجاهدةَ نفسك على البذلِ والتطهّرَ من الشحِّ من أعمالك."}},{"n":38,"reflection":{"text":"«ها أنتم هؤلاء تدعون لتنفقوا في سبيل الله فمنكم من يبخل ومن يبخل فإنما يبخل عن نفسه والله الغني وأنتم الفقراء وإن تتولوا يستبدل قوما غيركم ثم لا يكونوا أمثالكم»: ها أنتم تُدعَون للإنفاقِ في سبيلِ الله فمنكم من يبخل، ومن يبخل فإنما يبخل عن نفسه، والله الغنيُّ وأنتم الفقراء، وإن تتولّوا يستبدل قومًا غيركم لا يكونون مثلكم في البخل؛ ففي هذا الحثُّ على الإنفاقِ وبيانُ أنّ البخلَ ضررُه على صاحبه؛ فأنفق في سبيلِ الله ولا تبخل، فالله غنيٌّ عنك وأنت الفقيرُ إليه، فمن بخل ضرَّ نفسه، فاجعل الإنفاقَ في سبيلِ الله دأبك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنفاقُ في سبيلِ الله وتركُ البخل، وإدراكُ الفقرِ إلى الله."},"action":{"text":"تأمّل الحثَّ على الإنفاق: ها أنتم، أيها المؤمنون، هؤلاء تُدعَون لتنفقوا القليلَ في سبيلِ الله؛ فمنكم من يبخل بالإنفاق؛ ومن يبخل فإنما يبخل عن نفسه ويمنعها الثوابَ والخير، فضررُ بخله عليه؛ والله الغنيُّ عنكم وعن أموالكم، وأنتم الفقراء إليه المحتاجون؛ وإن تتولّوا وتعرضوا عن طاعته يستبدل قومًا غيركم أطوعَ منكم، ثم لا يكونوا أمثالكم في البخلِ والتولّي، بل يكونون خيرًا منكم «ها أنتم هؤلاء تدعون لتنفقوا في سبيل الله... ثم لا يكونوا أمثالكم»؛ ففي هذا الحثُّ على الإنفاقِ في سبيلِ الله، وبيانُ أنّ البخلَ ضررُه على صاحبه، وأنّ الله غنيٌّ والعبادَ فقراءُ إليه، والتهديدُ بالاستبدال؛ فمن بخل حرم نفسه الأجر؛ فأنفق أنت في سبيلِ الله ولا تبخل؛ فالله غنيٌّ عنك وعن مالك، وأنت الفقيرُ المحتاجُ إليه؛ يا أيها الناس أنتم الفقراء إلى الله والله هو الغنيُّ الحميد؛ ومن يبخل فإنما يبخل عن نفسه؛ ما عندكم ينفد وما عند الله باق؛ واحذر التولّي عن الطاعةِ فيستبدلك الله بقومٍ خيرٍ منك؛ وإن تتولّوا يستبدل قومًا غيركم ثم لا يكونوا أمثالكم؛ فمن أنفق ولم يبخل أفلح، ومن بخل وتولّى خسر واستُبدِل؛ فاجعل الإنفاقَ في سبيلِ الله دأبك، وإدراكَ فقرك إلى الله دائمًا؛ فبالإنفاقِ وتركِ البخلِ تنفع نفسك وتنال الأجر."}}]}],"coverage":{"covered":38,"total":38}};
